                bal[i] = bal[i - 1] + (a[i] % 2 == 0 ? 1 : -1);
            }
        }
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for(int i = 1; i < n - 1; ++i) {
            if(bal[i] == 0) {
                pq.offer(abs(a[i + 1] - a[i]));
            }
        }
