public class cf998b {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int b = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; ++i) {
            a[i] = sc.nextInt();
        }
        int[] bal = new int[n];
        for (int i = 0; i < n; ++i) {
            bal[i] = (i == 0 ? 0 : bal[i - 1]) + (a[i] % 2 == 0 ? 1 : -1);
        }
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 1; i < n - 1; ++i) {
            if (bal[i] == 0) {
                pq.offer(Math.abs(a[i + 1] - a[i]));
            }
        }
        int ans = 0;
        while (!pq.isEmpty() && b >= pq.peek()) {
            b -= pq.poll();
            ++ans;
        }
        System.out.println(ans);
        sc.close();
    }
}

