public class Solution
{
    static class FastReader
    {
        private BufferedInputStream in;
        private int next;

        FastReader(InputStream is)
        {
            in = new BufferedInputStream(is);
            next = read();
        }

        private int read()
        {
            try
            {
                return in.read();
            }
            catch (IOException e)
            {
                throw new RuntimeException(e);
            }
        }

        private boolean isSpace(int c)
        {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int nextInt()
        {
            while (next != -1 && isSpace(next))
            {
                next = read();
            }
            if (next == -1) throw new InputMismatchException();

            int sign = 1;
            if (next == '-')
            {
                sign = -1;
                next = read();
            }

            int val = 0;
            while (next != -1 && !isSpace(next))
            {
                val = val * 10 + (next - '0');
                next = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws IOException
    {
        FastReader fr = new FastReader(System.in);
        int n = fr.nextInt();
        int b = fr.nextInt();

        int[] a = new int[n];
        for (int i = 0; i < n; i++)
        {
            a[i] = fr.nextInt();
        }

        int[] odd = new int[n + 1];
        int[] even = new int[n + 1];

        for (int i = 1; i <= n; i++)
        {
            if ((a[i - 1] & 1) == 1)
            {
                odd[i] = odd[i - 1] + 1;
                even[i] = even[i - 1];
            }
            else
            {
                odd[i] = odd[i - 1];
                even[i] = even[i - 1] + 1;
            }
        }

        List<Integer> costs = new ArrayList<Integer>();
        int prev = 0;

        for (int i = 1; i < n; i++)
        {
            if (odd[i] - odd[prev] == even[i] - even[prev])
            {
                costs.add(Math.abs(a[i] - a[i - 1]));
                prev = i;
            }
        }

        Collections.sort(costs);
        int total = 0;
        int ans = 0;

        for (int c : costs)
        {
            if (total + c > b) break;
            total += c;
            ans++;
        }

        System.out.println(ans);
    }
}

