        int even = 0, odd = 0 ;
        for(int i=0;i<n;i++){
            if((a[i] & 1) == 0) even++ ;
            else odd++ ;

            if(even == odd && i < n-1){
                int c = Math.abs(a[i+1] - a[i]) ;
                counts.merge(c, 1, Integer::sum) ;
            }
        }

        int cnt = 0, sum = 0 ;
        for(Map.Entry<Integer,Integer> e : counts.entrySet()){
            int c = e.getKey() ;
            int left = e.getValue() ;
            while(left > 0 && sum + c <= B){
                sum += c ;
                cnt++ ;
                left-- ;
            }
            if(left > 0) break ;
        }

        System.out.println(cnt) ;
    }
