        int[] a = new int[n] ;
        for(int i=0;i<n;i++){
            a[i] = in.nextInt() ;
        }

        List<Integer> list = new ArrayList<>() ;
        int balance = 0 ;
        for(int i=0;i<n;i++){
            if((a[i] & 1) == 0) balance++ ;
            else balance-- ;

            if(balance == 0 && i+1 < n){
                list.add(Math.abs(a[i+1] - a[i])) ;
            }
        }

        int[] costs = new int[list.size()] ;
        for(int i=0;i<costs.length;i++){
            costs[i] = list.get(i) ;
        }
        Arrays.sort(costs) ;

        long[] pref = new long[costs.length + 1] ;
        for(int i=0;i<costs.length;i++){
            pref[i+1] = pref[i] + costs[i] ;
        }

        int lo = 0, hi = costs.length, answer = 0 ;
        while(lo <= hi){
            int mid = (lo + hi) >>> 1 ;
            if(pref[mid] <= B){
                answer = mid ;
                lo = mid + 1 ;
            }else{
                hi = mid - 1 ;
            }
        }

        System.out.println(answer) ;
    }
}

