public class CF998B {
    static class FastScanner {
        private BufferedInputStream in = new BufferedInputStream(System.in);
        private int nextInt() throws IOException {
            int c;
            do {
                c = in.read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = in.read();
            }
            int val = 0;
            while (c > ' ' && c != -1) {
                val = val * 10 + (c - '0');
                c = in.read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws IOException {
