        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int B = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < arr.length; i++) {
            arr[i] = sc.nextInt();
        }

        TreeMap<Integer, Integer> buckets = new TreeMap<>();
        int sum = 0;

        int evens = 0;
        int odds = 0;
        int start = 0;
        int count = 0;
        int k = 1;

        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] % 2 == 0) {
                evens++;
            } else {
                odds++;
            }

            if (evens == odds) {
                int diff = Math.abs(arr[i + 1] - arr[i]);
                int max = bucketMax(buckets);
                if (sum > B && diff < max) {
                    sum -= max;
                    buckets.put(max, buckets.get(max) - 1);
                    if (buckets.get(max) == 0) buckets.remove(max);
                    buckets.put(diff, buckets.getOrDefault(diff, 0) + 1);
                    sum += diff;
                } else if (sum < B) {
                    sum += diff;
                    buckets.put(diff, buckets.getOrDefault(diff, 0) + 1);
                    count++;
                    start = i + 1;
                }
                if (i == arr.length - 2 && k < arr.length - 1) {
                    i = start++;
                    evens = odds = 0;
                }
            }

        }
        while (sum > B) {
            int maxKey = buckets.lastKey();
            if (buckets.get(maxKey) > 0) {
                sum -= maxKey;
                count--;
                buckets.put(maxKey, buckets.get(maxKey) - 1);
                if (buckets.get(maxKey) == 0) buckets.remove(maxKey);
            }
        }

        System.out.println(count);
    }

    private static int bucketMax(TreeMap<Integer, Integer> buckets) {
        if (buckets.isEmpty()) return -1;
        return buckets.lastKey();
    }
}

