public class Cutting {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        String input = s.nextLine();
        int n = Integer.parseInt(input.split(" ")[0]);
        int bitCoins = Integer.parseInt(input.split(" ")[1]);
        String[] values = s.nextLine().split(" ");

        Map<Integer, Integer> costFrequency = new TreeMap<Integer, Integer>();
        int odd = 0;
        int even = 0;

        for (int i = 0; i < n - 1; i++) {
            if (Integer.parseInt(values[i]) % 2 == 0) {
                even++;
            } else {
                odd++;
            }
            if (odd == even) {
                int diff = Integer.parseInt(values[i + 1]) - Integer.parseInt(values[i]);
                if (diff < 0) {
                    diff = -diff;
                }
                Integer previous = costFrequency.get(diff);
                costFrequency.put(diff, previous == null ? 1 : previous + 1);
            }
        }

        int count = 0;
        for (Map.Entry<Integer, Integer> entry : costFrequency.entrySet()) {
            int cost = entry.getKey();
            int freq = entry.getValue();
            while (freq > 0 && cost <= bitCoins) {
                bitCoins -= cost;
                count++;
                freq--;
            }
            if (cost > bitCoins) {
                break;
            }
        }
        System.out.println(count);
    }
}

