import java.util.*;

public class Cutting {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        String input = s.nextLine();
        int n = Integer.parseInt(input.split(" ")[0]);
        int bitCoins = Integer.parseInt(input.split(" ")[1]);
        String[] values = s.nextLine().split(" ");

        List<Integer> costs = new ArrayList<Integer>();
        int odd = 0;
        int even = 0;

        for (int i = 0; i < n - 1; i++) {
            if (Integer.parseInt(values[i]) % 2 == 0) {
                even++;
            } else {
                odd++;
            }
            if (odd == even) {
                int diff = Integer.parseInt(values[i + 1]) - Integer.parseInt(values[i]);
                if (diff < 0) {
                    diff = -diff;
                }
                costs.add(diff);
            }
        }

        int[] state = {bitCoins, 0};
        costs.stream()
             .sorted()
             .allMatch(cost -> {
                 if (cost > state[0]) {
                     return false;
                 }
                 state[0] -= cost;
                 state[1]++;
                 return true;
             });
        System.out.println(state[1]);
    }
}

