        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        System.out.println(countCuts(a, budget));
    }

    private static int countCuts(int[] a, int budget) {
        int[] costs = new int[a.length];
        int size = 0;
        int evens = a[0] % 2 == 0 ? 1 : 0;
        int odds = a[0] % 2 == 1 ? 1 : 0;

        for (int i = 1; i < a.length; i++) {
            if (odds == evens && Math.abs(a[i] - a[i - 1]) <= budget) {
                evens = 0;
                odds = 0;
                costs[size++] = Math.abs(a[i] - a[i - 1]);
            }
            if (a[i] % 2 == 0) {
                evens++;
            } else {
                odds++;
            }
        }

        int[] sorted = Arrays.copyOf(costs, size);
        Arrays.sort(sorted);

        int answer = 0;
        for (int cost : sorted) {
            if (budget < cost) {
                break;
            }
            answer++;
            budget -= cost;
        }
        return answer;
    }
}

