public class Cutting{

    public static int[]strToIntArr(String s){
        String[] sArr = s.split(" ");
        int len = sArr.length;
        int[] retArr = new int[len];
        for(int i=0;i<len;i++){
            retArr[i] = Integer.parseInt(sArr[i]);
        }
        return retArr;
    }

    boolean checkSub(int[]aArr,int splitInd){
        int nEven = 0;
        int nOdd = 0;
        for(int i=0;i<=splitInd;i++){
            if((aArr[i]%2)==0) nEven++;
            else nOdd++;
        }
        return nEven==nOdd;
    }

    int getMaxCuts(int n, int b, int[]aArr){
        List<Integer> remaining = new ArrayList<Integer>();
        for(int i=1;i<aArr.length-1;i++){
            if(checkSub(aArr,i)){
                remaining.add(i);
            }
        }
        int nCoins = b;
        int nCuts = 0;
        while(nCoins>0 && !remaining.isEmpty()){
            int bestCost = nCoins + 1;
            int bestPos = -1;
            for(int j=0;j<remaining.size();j++){
                int idx = remaining.get(j);
                int cost = Math.abs(aArr[idx]-aArr[idx+1]);
                if(cost < bestCost){
                    bestCost = cost;
                    bestPos = j;
                }
            }
            if(bestPos==-1) break;
            remaining.remove(bestPos);
            nCoins -= bestCost;
            nCuts++;
        }
        return nCuts;
    }

    public static void main(String[]args) throws Exception{
