            int[] pairU = new int[n];
            int[] pairV = new int[n];
            int[] dist = new int[n];
            Arrays.fill(pairU, -1);
            Arrays.fill(pairV, -1);
            int INF = Integer.MAX_VALUE;
            int matching = 0;

            while (bfs(g, cols, pairU, pairV, dist, INF)) {
                for (int u = 0; u < n; u++) {
                    int r = u / cols;
                    int c = u % cols;
                    if (((r + c) & 1) == 0 && pairU[u] == -1 && dfs(u, g, pairU, pairV, dist, INF)) {
                        matching++;
                    }
                }
            }
            return matching;
        }

        static boolean bfs(List<Integer>[] g, int cols, int[] pairU, int[] pairV, int[] dist, int INF) {
            Queue<Integer> q = new ArrayDeque<>();
            for (int u = 0; u < g.length; u++) {
                int r = u / cols;
                int c = u % cols;
                if (((r + c) & 1) == 0 && pairU[u] == -1) {
                    dist[u] = 0;
                    q.add(u);
                } else {
                    dist[u] = INF;
                }
            }
            boolean found = false;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : g[u]) {
                    if (pairV[v] == -1) {
                        found = true;
                    } else if (dist[pairV[v]] == INF) {
                        dist[pairV[v]] = dist[u] + 1;
                        q.add(pairV[v]);
                    }
                }
            }
            return found;
        }

        static boolean dfs(int u, List<Integer>[] g, int[] pairU, int[] pairV, int[] dist, int INF) {
            for (int v : g[u]) {
                if (pairV[v] == -1 || (dist[pairV[v]] == dist[u] + 1 && dfs(pairV[v], g, pairU, pairV, dist, INF))) {
                    pairU[u] = v;
                    pairV[v] = u;
                    return true;
                }
            }
            dist[u] = INF;
            return false;
        }
    }

    static class InputReader {
        final InputStream is;
        final byte[] buf = new byte[1024];
        int pos;
        int size;

        public InputReader(InputStream is) {
            this.is = is;
        }

        public int nextInt() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isWhitespace(c));
            return res * sign;
        }

        int read() {
            if (size == -1) throw new InputMismatchException();
            if (pos >= size) {
                pos = 0;
                try {
                    size = is.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (size <= 0) return -1;
            }
            return buf[pos++] & 255;
        }

        static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

