        }

        private int read() {
            try {
                return in.read();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        private boolean delim(int c) {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
        }

        int nextInt() {
            int c = read();
            while (c != -1 && delim(c)) {
                c = read();
            }

            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }

            int value = 0;
            while (c != -1 && !delim(c)) {
                value = value * 10 + (c - '0');
                c = read();
            }

            return neg ? -value : value;
        }
    }

