public class CFA2 {
    private BufferedReader br;
    private StringTokenizer st;

    private static long MOD = 998244353L;
    private static int[] dx = {0, -1, 0, 1};
    private static int[] dy = {1, 0, -1, 0};

    void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        if (n > m) { int t = n; n = m; m = t; }

        if (n == 1) {
            m--;
            int[] left = {0,0,0,2,4,6};
            long res = m / 6 * 6 + left[m % 6];
            System.out.println(res);
            return;
        } else if (n == 2) {
            System.out.println(m < 20 ? bruteForce(n, m) : (long)n * m);
            return;
        } else if (n == 3) {
            if (m < 20) {
                System.out.println(bruteForce(n, m));
            } else {
                long res = (long)n * m;
                if ((res & 1) != 0) res--;
                System.out.println(res);
            }
            return;
        }

        long res = (long)n * m;
        if (res < 1000) {
            System.out.println(bruteForce(n, m));
        } else {
            if ((res & 1) != 0) res--;
            System.out.println(res);
        }
    }

    int bruteForce(int n, int m) {
        int es = n * m / 2 + (n * m % 2);
        int os = n * m / 2;
        int[] ex = new int[es], ey = new int[es];
        int[] ox = new int[os], oy = new int[os];
        int ei = 0, oi = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (((i + j) & 1) == 0) {
                    ex[ei] = i; ey[ei] = j; ei++;
                } else {
                    ox[oi] = i; oy[oi] = j; oi++;
                }
            }
        }

        ArrayList<Integer>[] adj = new ArrayList[es];
        for (int i = 0; i < es; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < es; i++) {
            for (int j = 0; j < os; j++) {
                if (Math.abs(ex[i] - ox[j]) + Math.abs(ey[i] - oy[j]) == 3) {
                    adj[i].add(j);
                }
            }
        }

        return 2 * maxMatching(adj, os);
    }

    int maxMatching(ArrayList<Integer>[] adj, int n2) {
        int[] matchR = new int[n2];
        Arrays.fill(matchR, -1);
        int result = 0;
        for (int u = 0; u < adj.length; u++) {
            boolean[] seen = new boolean[adj.length];
            if (dfs(adj, u, seen, matchR)) result++;
        }
        return result;
    }

    boolean dfs(ArrayList<Integer>[] adj, int u, boolean[] seen, int[] matchR) {
        for (int v : adj[u]) {
            if (!seen[v]) {
                seen[v] = true;
                if (matchR[v] == -1 || dfs(adj, matchR[v], seen, matchR)) {
                    matchR[v] = u;
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        new CFA2().solve();
    }

    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    CFA2() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
    }
}

import java.util.*;
import java.io.*;

public class CFA3 {
    BufferedReader br;
    PrintWriter out;
    StringTokenizer st;

    private static long MOD = 998244353L;

    void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        if (n > m) { int t = n; n = m; m = t; }

        if (n == 1) {
            m--;
            int[] left = {0,0,0,2,4,6};
            out.println(m / 6 * 6 + left[m % 6]);
        } else if (n == 2) {
            out.println(m < 20 ? bruteForce(n, m) : (long)n * m);
        } else if (n == 3) {
            if (m < 20) out.println(bruteForce(n, m));
            else {
                long res = (long)n * m;
                if ((res & 1) == 1) res--;
                out.println(res);
            }
        } else {
            long res = (long)n * m;
            if (res < 1000) out.println(bruteForce(n, m));
            else {
                if ((res & 1) == 1) res--;
                out.println(res);
            }
        }
    }

    int bruteForce(int n, int m) {
        int[][] grid = new int[n][m];
        int cnt = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                grid[i][j] = cnt++;

        int evenCount = (n * m + 1) / 2;
        int oddCount = n * m / 2;
        int[][] even = new int[evenCount][2];
        int[][] odd = new int[oddCount][2];
        int ei = 0, oi = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (((i + j) & 1) == 0) { even[ei][0] = i; even[ei][1] = j; ei++; }
                else { odd[oi][0] = i; odd[oi][1] = j; oi++; }
            }
        }

        boolean[][] match = new boolean[evenCount][oddCount];
        for (int i = 0; i < evenCount; i++) {
            for (int j = 0; j < oddCount; j++) {
                int d = Math.abs(even[i][0] - odd[j][0]) + Math.abs(even[i][1] - odd[j][1]);
                if (d == 3) match[i][j] = true;
            }
        }

        return 2 * maxMatching(match);
    }

    int maxMatching(boolean[][] g) {
        int n1 = g.length, n2 = n1 == 0 ? 0 : g[0].length;
        int[] matchR = new int[n2];
        Arrays.fill(matchR, -1);
        int res = 0;
        for (int u = 0; u < n1; u++) {
            if (bpm(g, u, new boolean[n1], matchR)) res++;
        }
        return res;
    }

    boolean bpm(boolean[][] g, int u, boolean[] seen, int[] matchR) {
        for (int v = 0; v < matchR.length; v++) {
            if (g[u][v] && !seen[v]) {
                seen[v] = true;
                if (matchR[v] == -1 || bpm(g, matchR[v], seen, matchR)) {
                    matchR[v] = u;
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        new CFA3().run();
    }

    void run() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }
}

