import java.util.*;
import java.util.function.LongUnaryOperator;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();

        LongUnaryOperator one = max -> {
            long rem = max % 6;
            long result = max - rem;
            if (rem == 4) result += 2;
            if (rem == 5) result += 4;
            return result;
        };

        LongUnaryOperator two = max -> {
            if (max < 3) return 0L;
            if (max == 3) return 4L;
            if (max == 7) return 12L;
            return 2L * max;
        };

        LongUnaryOperator three = max -> {
            if (max < 3) return 0L;
            long result = 3L * max;
            if ((max & 1L) == 1L) --result;
            return result;
        };

        long rep;
        if (n >= 4 && m >= 4) {
            rep = n * m;
            if ((n & 1L) != 0 && (m & 1L) != 0) {
                --rep;
            }
        } else {
            long min = Math.min(n, m);
            long max = Math.max(n, m);

            if (min == 1) {
                rep = one.applyAsLong(max);
            } else if (min == 2) {
                rep = two.applyAsLong(max);
            } else if (min == 3) {
                rep = three.applyAsLong(max);
            } else {
                rep = 0L;
            }
        }

        System.out.println(rep);
    }
}

