            to[edgeCnt] = v;
            nxt[edgeCnt] = head[u];
            head[u] = edgeCnt++;
        }
    }

    static class HopcroftKarp {
        static final int INF = 10000000;
        static final int NIL = 0;

        int m, n;
        int[] head, to, nxt;
        int[] pairU, pairV, dist;

        HopcroftKarp(int m, int n, int[] head, int[] to, int[] nxt) {
            this.m = m;
            this.n = n;
            this.head = head;
            this.to = to;
            this.nxt = nxt;
            pairU = new int[m + 1];
            pairV = new int[n + 1];
            dist = new int[m + 1];
        }

        int maxMatching() {
            Arrays.fill(pairU, NIL);
            Arrays.fill(pairV, NIL);
            int res = 0;
            while (bfs()) {
                for (int i = 1; i <= m; i++) {
                    if (pairU[i] == NIL && dfs(i)) res++;
                }
            }
            return res;
        }

        boolean bfs() {
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            for (int i = 1; i <= m; i++) {
                if (pairU[i] == NIL) {
                    queue.add(i);
                    dist[i] = 0;
                } else {
                    dist[i] = INF;
                }
            }
            dist[NIL] = INF;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                if (dist[u] < dist[NIL]) {
                    for (int e = head[u]; e != -1; e = nxt[e]) {
                        int v = to[e];
                        if (dist[pairV[v]] == INF) {
                            queue.add(pairV[v]);
                            dist[pairV[v]] = dist[u] + 2;
                        }
                    }
                }
            }
            return dist[NIL] < INF;
        }

        boolean dfs(int u) {
            if (u == NIL) return true;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (dist[pairV[v]] == dist[u] + 2) {
                    if (dfs(pairV[v])) {
                        pairV[v] = u;
                        pairU[u] = v;
                        return true;
                    }
                }
            }
            dist[u] = INF;
            return false;
        }
    }

