    static long solve(long r, long c) {
        if (r < 3 && c < 3) return 0L;
        if (r == 1) {
            long m = c % 6;
            switch ((int) m) {
                case -5: return c + 5L;
                case -4: return c + 4L;
                case -3: return c + 3L;
                case -2: return c + 2L;
                case -1: return c + 1L;
                case 0: return c;
                case 1: return c - 1L;
                case 2: return c - 2L;
                case 3: return c - 3L;
                case 4: return c - 2L;
                default: return c - 1L;
            }
        }
        if (r == 2) {
            return (c == 3 || c == 7) ? 2L * (c - 1) : 2L * c;
        }
        long total = r * c;
        return (total & 1L) == 0L ? total : total - 1L;
    }
