import java.util.function.LongBinaryOperator;

public class B {
    static PrintWriter out = new PrintWriter(System.out);

    private static final LongBinaryOperator SOLVE = (r, c) -> {
        if (r < 3 && c < 3) return 0L;
        if (r == 1) return oneRow(c);
        if (r == 2) return twoRows(c);
        return (r * c) & ~1L;
    };

    public static void main(String[] args) {
        FS in = new FS();
        long R = in.nextLong();
        long C = in.nextLong();
        out.println(SOLVE.applyAsLong(Math.min(R, C), Math.max(R, C)));
        out.close();
    }

    private static long oneRow(long c) {
        long m = c % 6;
        if (m == 0) return c;
        if (m <= 3) return c - m;
        if (m == 4) return c - 2;
        return c - 1;
    }

    private static long twoRows(long c) {
        if (c == 3 || c == 7) return 2L * (c - 1);
        return 2L * c;
    }

    static class FS {
        BufferedReader br;
        StringTokenizer st;

        public FS() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw null;
                }
            }
            return st.nextToken();
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class P1047D
{
	static int[][] grid;
	static int R, C;
	public static void main(String[] args)
	{
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int m = scan.nextInt();
		long min = Math.min(n, m);
		long max = Math.max(n, m);
		if (min == 1)
			System.out.println(max/6*6 + 2*Math.max(0, max%6-3));
		else if (min == 2 && max == 2)
			System.out.println(0);
		else if (min == 2 && max == 3)
			System.out.println(4);
		else if (min == 3 && max == 3)
			System.out.println(8);
		else if (min == 2 && max == 7)
			System.out.println(12);
		else if (max%2 == 0)
			System.out.println(min*max);
		else // if (max%2 == 1)
			System.out.println(min*max - min*max%2);
	}
	private static boolean can(int cur, int r, int c)
	{
		if (cur > R*C/2)
		{
//			for (int i = 0; i < grid.length; i++)
//			{
//				for (int j = 0; j < grid[0].length; j++)
//					System.out.printf("%3d", grid[i][j]);
//				System.out.println();
//			}
//			System.out.println();
			return true;
		}
		if (c >= C)
			return can(cur, r+1, 0);
		if (grid[r][c] != 0)
			return can(cur, r, c+1);
		grid[r][c] = cur;
		for (int dr = 0; dr <= 3; dr++)
		{
			for (int dc = -2; dc <= 3; dc++)
			{
				if (dr+Math.abs(dc) != 3)
					continue;
				if (ok(r+dr, c+dc))
				{
					grid[r+dr][c+dc] = cur;
					if (can(cur+1, r, c+1))
						return true;
					grid[r+dr][c+dc] = 0;
				}
			}
		}
		grid[r][c] = 0;
		return false;
	}
	private static boolean ok(int r, int c)
	{
		return r >= 0 && c >= 0 && r < R && c < C && grid[r][c] == 0;
	}
}

