        if (b == '-' || b == '+') {
            if (b == '-') {
                sign = -1;
            }
            b = in.read();
        }

        int value = 0;
        while (b != -1 && b > ' ') {
            value = value * 10 + (b - '0');
            b = in.read();
        }

        return value * sign;
    }
}

