        long n = in.nextInt();
        long m = in.nextInt();

        System.out.println(solve(n, m));
    }

    private static long solve(long n, long m) {
        if (n > m) {
            return solve(m, n);
        }

        if (n == 1) {
            long[] correction = {0, 1, 2, 3, 2, 1};
            return n * m - correction[(int) (m % 6)];
        }

        if (n == 2) {
            if (m == 2) {
                return n * m - 4;
            }
            if (m == 3 || m == 7) {
                return n * m - 2;
            }
            return n * m;
        }

        if (n == 3) {
            return n * m - (m & 1L);
        }

        return n * m - ((n & 1L) & (m & 1L));
    }
}

