    static long readLong(InputStream in) throws IOException {
        int c;
        do {
            c = in.read();
        } while (c != -1 && c <= ' ');
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = in.read();
        }
        long value = 0;
        while (c != -1 && c > ' ') {
            value = value * 10 + (c - '0');
            c = in.read();
        }
        return negative ? -value : value;
    }

    static long compute(long n, long m) {
        if (m < n) {
            long t = n;
            n = m;
            m = t;
        }
        if (n == 1) return oneRow(m);
        if (n == 2) return twoRows(m);
        return 2 * (n * m / 2);
    }

    static long oneRow(long m) {
        long ans = 6 * (m / 6);
        if (m % 6 == 5) ans += 4;
        else if (m % 6 == 4) ans += 2;
        return ans;
    }

    static long twoRows(long m) {
        if (m < 3) return 0;
        if (m == 3) return 4;
        if (m == 7) return 12;
        return 2 * m;
