    }

    static long compute(long n, long m) {
        if (m < n) {
            n = n ^ m;
            m = n ^ m;
            n = n ^ m;
        }
        if (n == 1) return bruteRow(m);
        if (n == 2) {
            if (m < 3) return 0;
            if (m == 3) return 4;
            if (m == 7) return 12;
            return 2 * m;
