import java.io.*;
import java.util.*;

public class Perturbed2 {
    static class FastReader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) return -ret;
            return ret;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = din.read(buffer, 0, BUFFER_SIZE);
                if (bytesRead == -1) buffer[0] = -1;
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader scan = new FastReader();
        long MOD = 1000000007L;
        int n = scan.nextInt();
        long[] prev = new long[n + 2];
        prev[0] = 1;
        long s = 0;
        for (int i = 1; i < 2 * n + 1; i++) {
            long[] cur = new long[n + 2];
            int maxJ = Math.min(n, 2 * n - i);
            cur[0] = prev[1] % MOD;
            for (int j = 1; j <= maxJ; j++) {
                cur[j] = (prev[j + 1] + prev[j - 1]) % MOD;
            }
            if (i % 2 == 1) {
                for (int j = 0; j <= n; j++) {
                    s = (s + cur[j]) % MOD;
                }
            }
            prev = cur;
        }
        System.out.println(s);
    }
}

import java.util.Scanner;

public class Perturbed3 {
    static Scanner scan = new Scanner(System.in);
    static Long[][] memo;
    static int n;
    static long MOD = 1000000007L;

    static long get(int i, int j) {
        if (j < 0 || j > n + 1 || i < 0 || i > 2 * n || j + i > 2 * n) return 0;
        if (i == 0) {
            if (j == 0) return 1;
            else return 0;
        }
        if (memo[i][j] != null) return memo[i][j];
        long res;
        if (j == 0) {
            res = get(i - 1, 1) % MOD;
        } else {
            res = (get(i - 1, j + 1) + get(i - 1, j - 1)) % MOD;
        }
        memo[i][j] = res;
        return res;
    }

    public static void main(String[] args) {
        n = scan.nextInt();
        memo = new Long[2 * n + 1][n + 2];
        long s = 0;
        for (int i = 1; i < 2 * n; i += 2) {
            for (int j = 0; j <= n; j++) {
                s = (s + get(i, j)) % MOD;
            }
        }
        System.out.println(s);
    }
}

