import java.io.IOException;
import java.util.Scanner;

public class NekoAndAkiPrank {
    private final static long MOD = 1_000_000_007;

    public void solve() throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[][] ways = new long[2][n + 1];
        long tWays = 0;
        ways[0][0] = 1;
        for (int i = 1; i < 2 * n; i += 2) {
            int prevIdx = (i - 1) % 2;
            int curIdx = i % 2;
            ways[curIdx][0] = ways[prevIdx][1];
            ways[curIdx][n] = ways[prevIdx][n - 1];
            for (int k = 1; k < n; k++) {
                ways[curIdx][k] = (ways[prevIdx][k - 1] + ways[prevIdx][k + 1]) % MOD;
            }
            int limit = Math.min(i, 2 * n - i);
            for (int k = 0; k <= limit; k++) {
                tWays = (tWays + ways[curIdx][k]) % MOD;
            }
            if (i + 1 < 2 * n) {
                int nextIdx = (i + 1) % 2;
                ways[nextIdx][0] = ways[curIdx][1];
                ways[nextIdx][n] = ways[curIdx][n - 1];
                for (int k = 1; k < n; k++) {
                    ways[nextIdx][k] = (ways[curIdx][k - 1] + ways[curIdx][k + 1]) % MOD;
                }
            }
        }
        System.out.println(tWays);
    }

    public static void main(String[] args) throws IOException {
        NekoAndAkiPrank solution = new NekoAndAkiPrank();
        solution.solve();
    }
}

