import java.util.Scanner;

public class Main {
    private static Scanner sc = new Scanner(System.in);
    private static final int MOD = 1000000007;
    private static final int MAX = 2000;
    private static int[][] dp = new int[MAX + 5][MAX * 11 + 5];
    private static int[][] ok = new int[MAX + 5][MAX + 5];

    private static void compute(int i, int j) {
        if (i == 0) {
            ok[0][0] = 1;
            return;
        }
        if (ok[i][j] != 0) return; // already computed
        if (j == 0) {
            compute(i - 1, j + 1);
            dp[i][j] = dp[i - 1][j + 1];
            if (ok[i - 1][j + 1] == 1)
                dp[i][j] = (dp[i][j] + 1) % MOD;
            else
                ok[i][j] = 1;
        } else {
            compute(i - 1, j - 1);
            compute(i - 1, j + 1);
            dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j + 1]) % MOD;
            if (ok[i - 1][j + 1] == 1 || ok[i - 1][j - 1] == 1)
                dp[i][j] = (dp[i][j] + 1) % MOD;
            else
                ok[i][j] = 1;
        }
    }

    public static void main(String[] args) {
        for (int i = 1; i <= MAX; i++) {
            for (int j = i & 1; j <= i; j += 2) {
                compute(i, j);
            }
        }
        System.out.print(dp[2 * sc.nextInt()][0]);
    }
}

