        return new Matrix(1, 0, 0, 1);
    }

    static Matrix power(Matrix m, long e) {
        Matrix res = identity();
        while (e > 0) {
            if ((e & 1) == 1) res = res.multiply(m);
            m = m.multiply(m);
            e >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) sb.append(line).append(' ');
        String[] tokens = sb.toString().trim().split("\\s+");

        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        long L = Long.parseLong(tokens[2]);
        long R = Long.parseLong(tokens[3]);

        long h = R - L;
        long even, odd;
        if (h % 2 == 1) {
            long d = (h + 1) / 2;
            even = d;
            odd = d;
        } else {
            long d = h / 2;
            even = d;
            odd = d;
            if (L % 2 == 1) odd++;
            else even++;
        }

        Matrix mat = new Matrix(even % MOD, odd % MOD, odd % MOD, even % MOD);
        Matrix p = power(mat, n * m);
        long ans = p.a;
        if ((n * m) % 2 == 1) ans += p.b;
        System.out.println(ans % MOD);
    }
}

