                System.out.println(res[0]);
            }
        }
    }

    static long pow(long a, long b) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            b >>= 1;
        }
        return res;
    }

    static long[] matMul(long[] x, long[] y) {
        return new long[] {
            (x[0] * y[0] + x[1] * y[2]) % MOD,
            (x[0] * y[1] + x[1] * y[3]) % MOD,
            (x[2] * y[0] + x[3] * y[2]) % MOD,
            (x[2] * y[1] + x[3] * y[3]) % MOD
        };
    }

    static long[] matPow(long[] base, long exp) {
        BinaryOperator<long[]> multiply = (a, b) -> matMul(a, b);
        long[] res = { 1, 0, 0, 1 };
        long[] cur = base.clone();
