public class E {
    static final long mod = 998244353L;
    static Map<Long, Integer>[] dp = new Map[2];

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextInt();
        long m = in.nextInt();
        long p = in.nextInt();
        long q = in.nextInt();
        long total = q - p + 1;
        long x = total;
        if (p % 2 == 0) {
            x = x - x / 2;
        } else {
            x /= 2;
        }
        long y = total - x;

        dp[0] = new HashMap<>();
        dp[1] = new HashMap<>();

        if ((n & m) % 2 == 0) {
            System.out.println(fn(x, y, n * m, 0));
        } else {
            System.out.println(bin(x + y, n * m));
        }
    }

    private static long fn(long x, long y, long st, int type) {
        Integer cached = dp[type].get(st);
        if (cached != null) {
            return cached;
        }
        if (st == 1) {
            return type == 0 ? x : y;
        }
        if ((st & 1) == 1) {
            return (x * fn(x, y, st - 1, type) + y * fn(x, y, st - 1, 1 - type)) % mod;
        }
        long ch = fn(x, y, st / 2, 0);
        long nch = fn(x, y, st / 2, 1);
        long ans;
        if (type == 0) {
            ans = (ch * ch + nch * nch) % mod;
        } else {
            ans = (2 * ch * nch) % mod;
        }
        dp[type].put(st, (int) ans);
        return ans;
    }

    private static long bin(long x, long st) {
        if (st == 0) return 1;
        if (st == 1) return x;
        long result = 1;
        long cur = x;
        long e = st;
        while (e > 0) {
            if ((e & 1) == 1) {
