                res = (res * a) % MOD;
            }
            a = (a * a) % MOD;
            b >>= 1;
        }
        return res;
    }

    static long pairValue(long start) {
        ArrayDeque<Long> stack = new ArrayDeque<>();
        HashSet<Long> seen = new HashSet<>();
        ArrayList<Long> order = new ArrayList<>();

        stack.push(start);
        seen.add(start);

        while (!stack.isEmpty()) {
            long cur = stack.pop();
            order.add(cur);

            if (cur == 1 || cur == 2) {
                continue;
            }

            long half = cur / 2;
            long rest = cur - half;
            if (seen.add(half)) {
                stack.push(half);
            }
            if (seen.add(rest)) {
                stack.push(rest);
            }
        }

        Collections.sort(order);

        HashMap<Long, long[]> values = new HashMap<>();
        for (long cur : order) {
            if (cur == 1) {
                values.put(cur, new long[] { even, odd });
            } else if (cur == 2) {
                values.put(cur, new long[] {
                    (even * even + odd * odd) % MOD,
                    (even * odd + odd * even) % MOD
                });
            } else {
                long[] left = values.get(cur / 2);
                long[] right = values.get(cur - cur / 2);
                values.put(cur, new long[] {
                    (left[0] * right[0] + left[1] * right[1]) % MOD,
                    (left[0] * right[1] + left[1] * right[0]) % MOD
                });
            }
        }

        return values.get(start)[0];
    }

    static void solve() {
        long n = in.nextInt();
        long m = in.nextInt();
        long l = in.nextInt();
        long r = in.nextInt();
        long sz = n * m;

        if (sz % 2 == 0) {
            even = (r - l + 1) / 2;
            if ((r - l) % 2 == 0 && l % 2 == 0) {
                even++;
            }
            odd = r - l + 1 - even;
            out.println(pairValue(sz));
        } else {
            out.println(pow(r - l + 1, sz));
        }
    }

    public static void main(String[] args) {
        in = new FastReader(System.in);
        out = new PrintWriter(System.out);
        int tests = 1;
        while (tests-- > 0) {
            solve();
        }
        out.close();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        Integer nextInt() {
            return Integer.parseInt(next());
        }

        Long nextLong() {
            return Long.parseLong(next());
        }

        Double nextDouble() {
            return Double.parseDouble(next());
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        String nextLine() {
            String s = "";
            try {
                s = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return s;
        }
    }
}

