public class E {
    private static final BigInteger MOD = BigInteger.valueOf(998244353L);
    private static final long MOD_LONG = 998244353L;

    public static void main(String[] args) throws Exception {
        BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(infile.readLine());

        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        long cells = N * M;
        BigInteger base = BigInteger.valueOf(R - L + 1);
        BigInteger exponent = BigInteger.valueOf(cells);

        long value = powMod(base, exponent, MOD).longValue();

        if ((cells % 2L) == 1L) {
            System.out.println(value);
            return;
        }

        if (((R - L) % 2L) == 0L) {
            value++;
        }

        value = (value * ((MOD_LONG + 1) / 2L)) % MOD_LONG;
        System.out.println(value);
    }

    private static BigInteger powMod(BigInteger base, BigInteger exponent, BigInteger mod) {
        if (base.signum() < 0 || exponent.signum() < 0) {
            return base.modPow(exponent, mod);
        }

        BigInteger result = BigInteger.ONE;
        BigInteger factor = base.mod(mod);
        BigInteger e = exponent;

        while (e.signum() > 0) {
            if (e.testBit(0)) {
                result = result.multiply(factor).mod(mod);
            }
            e = e.shiftRight(1);
            factor = factor.multiply(factor).mod(mod);
        }

        return result;
    }
}

