import java.io.PrintWriter;
import java.util.BitSet;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        if (n <= 0 || n > 11) {
            out.println(0);
            out.close();
            return;
        }
        int[][] p = new int[n][5];
        for (int i = 0; i < n; i++) {
            p[i][0] = in.nextInt();
            p[i][1] = in.nextInt();
            p[i][2] = in.nextInt();
            p[i][3] = in.nextInt();
            p[i][4] = in.nextInt();
        }
        BitSet good = new BitSet(n);
        for (int i = 0; i < n; i++) {
            boolean ok = true;
            for (int j = 0; j < n && ok; j++) {
                for (int k = 0; k < n && ok; k++) {
                    if (i != j && i != k && j != k) {
                        int[] u = diff(p[j], p[i]);
                        int[] v = diff(p[k], p[i]);
                        if (isAcute(u, v)) {
                            ok = false;
                        }
                    }
                }
            }
            if (ok) good.set(i);
        }
        int cnt = good.cardinality();
        if (cnt == 0) {
            out.println(0);
        } else {
            out.println(cnt);
            for (int idx = good.nextSetBit(0); idx >= 0; idx = good.nextSetBit(idx + 1)) {
                out.println(idx + 1);
            }
        }
        out.close();
    }

    static int[] diff(int[] a, int[] b) {
        return new int[] {a[0]-b[0], a[1]-b[1], a[2]-b[2], a[3]-b[3], a[4]-b[4]};
    }

    static boolean isAcute(int[] a, int[] b) {
        int dot = a[0]*b[0] + a[1]*b[1] + a[2]*b[2] + a[3]*b[3] + a[4]*b[4];
        double ma = Math.sqrt(a[0]*a[0] + a[1]*a[1] + a[2]*a[2] + a[3]*a[3] + a[4]*a[4]);
        double mb = Math.sqrt(b[0]*b[0] + b[1]*b[1] + b[2]*b[2] + b[3]*b[3] + b[4]*b[4]);
        return Math.toDegrees(Math.acos(dot / (ma * mb))) < 90;
    }
}

