                    int v = p[k][d] - p[i][d];
                    dot += u * v;
                    a += u * u;
                    b += v * v;
                }
                double angle = Math.acos(dot / (Math.sqrt(a) * Math.sqrt(b)));
                if (angle < Math.PI / 2 - EPS) {
