import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    static class Point {
        long x1, x2, x3, x4, x5;

        Point(long a, long b, long c, long d, long e) {
            x1 = a;
            x2 = b;
            x3 = c;
            x4 = d;
            x5 = e;
        }

        Vector to(Point other) {
            return new Vector(
                other.x1 - x1,
                other.x2 - x2,
                other.x3 - x3,
                other.x4 - x4,
                other.x5 - x5
            );
        }
    }

    static class Vector {
        long x1, x2, x3, x4, x5;

        Vector(long a, long b, long c, long d, long e) {
            x1 = a;
            x2 = b;
            x3 = c;
            x4 = d;
            x5 = e;
        }

        boolean same(Vector other) {
            return x1 == other.x1 && x2 == other.x2 && x3 == other.x3 && x4 == other.x4 && x5 == other.x5;
        }

        long dot(Vector other) {
            return x1 * other.x1 + x2 * other.x2 + x3 * other.x3 + x4 * other.x4 + x5 * other.x5;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }

        Point[] points = new Point[n];
        for (int i = 0; i < n; i++) {
            points[i] = new Point(sc.nextLong(), sc.nextLong(), sc.nextLong(), sc.nextLong(), sc.nextLong());
        }

        List<Integer> bad = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            boolean found = false;
            for (int j = 0; j < n && !found; j++) {
                Vector vj = points[i].to(points[j]);
                for (int k = 0; k < n; k++) {
                    Vector vk = points[i].to(points[k]);
                    if (!vj.same(vk) && vj.dot(vk) > 0) {
                        bad.add(i + 1);
                        found = true;
                        break;
                    }
                }
            }
        }

        System.out.println(n - bad.size());
        for (int i = 1; i <= n; i++) {
            if (!bad.contains(i)) {
                System.out.println(i);
            }
        }
    }
}

