import java.util.*;

public class V1 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        char[] s = sc.next().toCharArray();
        int ans1 = 0, ans2 = 0;
        int i = 0;
        while (i < n) {
            switch (s[i]) {
                case '(':
                    int len = 0;
                    while (i + 1 < n) {
                        char next = s[i + 1];
                        if (next == ')') {
                            if (len > 0) ans2++;
                            break;
                        }
                        if (next == '_') {
                            if (len > 0) { ans2++; len = 0; }
                        } else {
                            len++;
                        }
                        i++;
                    }
                    break;
                case ')':
                case '_':
                    int len2 = 0;
                    while (i + 1 < n && s[i + 1] != ')' && s[i + 1] != '_' && s[i + 1] != '(') {
                        len2++;
                        i++;
                    }
                    ans1 = Math.max(ans1, len2);
                    break;
                default:
                    int len3 = 0;
                    while (i < n && s[i] != ')' && s[i] != '_' && s[i] != '(') {
                        len3++;
                        i++;
                    }
                    ans1 = Math.max(ans1, len3);
                    i--;
                    break;
            }
            i++;
        }
        System.out.println(ans1 + " " + ans2);
    }
}

import java.io.*;
import java.util.*;

public class V2 {
    BufferedReader in;
    StringTokenizer st;
    int n;
    char[] s;
    int ans1 = 0, ans2 = 0;

    public static void main(String[] args) throws IOException {
        new V2().run();
    }

    void run() throws IOException {
        in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter ob = new PrintWriter(System.out);
        n = Integer.parseInt(nextToken());
        s = nextToken().toCharArray();
        solve();
        ob.println(ans1 + " " + ans2);
        ob.flush();
    }

    void solve() {
        int i = 0;
        while (i < n) {
            if (s[i] == '(') {
                i = processInside(i);
            } else if (s[i] == ')' || s[i] == '_') {
                i = processSeparator(i);
            } else {
                i = processWord(i);
            }
            i++;
        }
    }

    int processInside(int i) {
        int c = 0;
        while (i + 1 < n) {
            char ch = s[i + 1];
            if (ch == ')') {
                if (c > 0) ans2++;
                return i;
            }
            if (ch == '_') {
                if (c > 0) ans2++;
                c = 0;
            } else {
                c++;
            }
            i++;
        }
        return i;
    }

    int processSeparator(int i) {
        int c = 0;
        while (i + 1 < n && !isSpecial(s[i + 1])) {
            c++;
            i++;
        }
        ans1 = Math.max(ans1, c);
        return i;
    }

    int processWord(int i) {
        int c = 0;
        while (i < n && !isSpecial(s[i])) {
            c++;
            i++;
        }
        ans1 = Math.max(ans1, c);
        return i - 1;
    }

    boolean isSpecial(char ch) {
        return ch == '(' || ch == ')' || ch == '_';
    }

    String nextToken() throws IOException {
        if (st == null || !st.hasMoreTokens())
            st = new StringTokenizer(in.readLine());
        return st.nextToken();
    }
}

