public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            int longest = 0;
            long inside = 0;
            StringBuilder outside = new StringBuilder();
            boolean endedWithMatch = false;
            int i = 0;
            int len = s.length();
            while (i < len) {
                char c = s.charAt(i);
                if (c == '(') {
                    int j = i + 1;
                    while (j < len && isWordChar(s.charAt(j))) {
                        j++;
                    }
                    if (j < len && s.charAt(j) == ')') {
                        longest = Math.max(longest, longestWords(outside.toString()));
                        outside.setLength(0);
                        inside += countInside(s.substring(i + 1, j));
                        i = j + 1;
                        endedWithMatch = true;
                        continue;
                    }
                }
                outside.append(c);
                i++;
                endedWithMatch = false;
            }
            if (!endedWithMatch || outside.length() > 0) {
                longest = Math.max(longest, longestWords(outside.toString()));
            }
            out.println(longest + " " + inside);
        }

        private boolean isWordChar(char c) {
            return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_';
        }

        private int longestWords(String line) {
            int best = 0;
            for (String word : line.split("_")) {
                best = Math.max(best, word.length());
            }
            return best;
        }

        private long countInside(String inner) {
            long count = 0;
            for (String part : inner.split("_")) {
                if (!part.isEmpty()) {
                    count++;
                }
            }
            return count;
        }
    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

