    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            int longest = 0;
            long inside = 0;
            int wordLen = 0;
            int i = 0;
            int len = s.length();
            while (i < len) {
                char c = s.charAt(i);
                if (c == '(') {
                    int j = i + 1;
                    while (j < len && isWordChar(s.charAt(j))) {
                        j++;
                    }
                    if (j < len && s.charAt(j) == ')') {
                        if (wordLen > longest) {
                            longest = wordLen;
                        }
                        wordLen = 0;
                        inside += countInside(s.substring(i + 1, j));
                        i = j + 1;
                        continue;
                    }
                }
                if (c == '_') {
                    if (wordLen > longest) {
                        longest = wordLen;
                    }
                    wordLen = 0;
                } else {
                    wordLen++;
                }
                i++;
            }
            if (wordLen > longest) {
                longest = wordLen;
            }
            out.println(longest + " " + inside);
        }

        private boolean isWordChar(char c) {
            return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_';
        }

        private long countInside(String inner) {
            long count = 0;
            for (String part : inner.split("_")) {
                if (!part.isEmpty()) {
                    count++;
                }
            }
            return count;
        }
