public class splitITup {

    static class ParenInfo {
        List<Integer> starts = new ArrayList<Integer>();
        List<Integer> ends = new ArrayList<Integer>();
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        String target = scan.next();

        ParenInfo info = new ParenInfo();
        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);
            if (c == '(') info.starts.add(i);
            if (c == ')') info.ends.add(i);
        }

        int count = countInside(info, target);
        int max = maxOutside(info, target);
        System.out.println(max + " " + count);
    }

    private static int countInside(ParenInfo info, String target) {
        int count = 0;
        for (int i = 0; i < info.ends.size(); i++) {
            String s = target.substring(info.starts.get(i) + 1, info.ends.get(i));
            for (String part : s.split("_")) {
                if (!part.isEmpty()) count++;
            }
        }
        return count;
    }

    private static int maxOutside(ParenInfo info, String target) {
        info.ends.add(0, 0);
        info.starts.add(target.length());

        int max = 0;
        int i = target.charAt(0) == '(' ? 1 : 0;
        for (; i < info.ends.size(); i++) {
            int from = target.charAt(info.ends.get(i)) == ')' ? info.ends.get(i) + 1 : info.ends.get(i);
            String s = target.substring(from, info.starts.get(i));
            for (String part : s.split("_")) {
                if (part.length() > max && !part.contains("(") && !part.contains(")")) {
                    max = part.length();
                }
            }
        }
        return max;
    }
}

