public class splitITup {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        String target = scan.next();

        List<Integer> starts = new ArrayList<Integer>();
        List<Integer> ends = new ArrayList<Integer>();
        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);
            if (c == '(') starts.add(i);
            if (c == ')') ends.add(i);
        }

        int count = (int) IntStream.range(0, ends.size())
            .mapToObj(i -> target.substring(starts.get(i) + 1, ends.get(i)))
            .flatMap(s -> Arrays.stream(s.split("_")))
            .filter(part -> !part.isEmpty())
            .count();

        ends.add(0, 0);
        starts.add(target.length());

        int begin = target.charAt(0) == '(' ? 1 : 0;
        int Max = IntStream.range(begin, ends.size())
            .map(i -> {
                int from = target.charAt(ends.get(i)) == ')' ? ends.get(i) + 1 : ends.get(i);
                String s = target.substring(from, starts.get(i));
                return Arrays.stream(s.split("_"))
                    .filter(part -> !part.contains("(") && !part.contains(")"))
                    .mapToInt(String::length)
                    .max()
                    .orElse(0);
            })
            .max()
            .orElse(0);

        System.out.println(Max + " " + count);
    }
}

import java.util.ArrayList;
