import java.util.Scanner;

public class splitITup {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        String target = scan.next();

        List<Integer> starts = new ArrayList<Integer>();
        List<Integer> ends = new ArrayList<Integer>();
        for (int i = 0; i < n; i++) {
            char c = target.charAt(i);
            if (c == '(') starts.add(i);
            if (c == ')') ends.add(i);
        }

        int count = 0;
        for (int i = 0; i < ends.size(); i++) {
            count += countTokens(target.substring(starts.get(i) + 1, ends.get(i)));
        }

        ends.add(0, 0);
        starts.add(target.length());

        int Max = 0;
        int i = target.charAt(0) == '(' ? 1 : 0;
        for (; i < ends.size(); i++) {
            int from = target.charAt(ends.get(i)) == ')' ? ends.get(i) + 1 : ends.get(i);
            String s = target.substring(from, starts.get(i));

            int len = 0;
            boolean bad = false;
            for (int k = 0; k < s.length(); k++) {
                char c = s.charAt(k);
                if (c == '_') {
                    if (!bad && len > Max) Max = len;
                    len = 0;
                    bad = false;
                } else {
                    len++;
                    if (c == '(' || c == ')') bad = true;
                }
            }
            if (!bad && len > Max) Max = len;
        }

        System.out.println(Max + " " + count);
    }

    private static int countTokens(String s) {
        int count = 0;
        boolean inToken = false;
        for (int k = 0; k < s.length(); k++) {
            if (s.charAt(k) == '_') {
                if (inToken) count++;
                inToken = false;
            } else {
                inToken = true;
            }
        }
        if (inToken) count++;
        return count;
    }
}

