        for (int idx = 0; idx < n; ++idx) {
            char ch = s.charAt(idx);
            if (ch == '_') {
                if (parenthesized) {
                    if (cur > 0) {
                        innerWords++;
                    } else {
                        outsideLongest = Math.max(outsideLongest, cur);
                    }
                } else {
                    outsideLongest = Math.max(outsideLongest, cur);
                }
                cur = 0;
            } else if (ch == '(') {
                parenthesized = true;
                outsideLongest = Math.max(outsideLongest, cur);
                cur = 0;
            } else if (ch == ')') {
                parenthesized = false;
                if (cur > 0) {
                    innerWords++;
                }
                cur = 0;
            } else {
                cur++;
            }
        }

