        boolean inside = false;

        for (char c : text.toCharArray()) {
            if (c == '(') {
                if (current > max) {
                    max = current;
                }
                current = 0;
                inside = true;
            } else if (c == ')') {
                inside = false;
            } else if (!inside) {
                if (c == '_') {
                    if (current > max) {
                        max = current;
                    }
                    current = 0;
                } else {
                    current++;
                }
            }
        }

        if (current > max) {
            max = current;
        }
        return max;
    }

    private static int wordsInside(String text) {
        int count = 0;
        int current = 0;
        boolean inside = false;

        for (char c : text.toCharArray()) {
            if (c == '(') {
                inside = true;
                current = 0;
            } else if (c == ')') {
                inside = false;
                if (current != 0) {
                    count++;
                }
                current = 0;
            } else if (inside) {
                if (c == '_') {
                    if (current != 0) {
                        count++;
                    }
                    current = 0;
                } else {
                    current++;
                }
            }
        }

        return count;
    }
}

