import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

public class ProblemB {

    private void solve(char[] a, PrintWriter out) {
        int one = 0;
        int two = 0;
        boolean inside = false;
        int chunkStart = 0;
        int p = nextParen(a, 0);
        while (p != -1) {
            int[] counts = { one, two };
            processChunk(a, chunkStart, p, inside, counts);
            one = counts[0];
            two = counts[1];
            inside = a[p] == '(';
            chunkStart = p + 1;
            p = nextParen(a, p + 1);
        }
        int[] counts = { one, two };
        processChunk(a, chunkStart, a.length, inside, counts);
        one = counts[0];
        two = counts[1];
        out.println(one + " " + two);
    }

    private int nextParen(char[] a, int from) {
        for (int i = from; i < a.length; i++) {
            if (a[i] == '(' || a[i] == ')') {
                return i;
            }
        }
        return -1;
    }

    private void processChunk(char[] a, int start, int end, boolean inside, int[] counts) {
        int i = start;
        while (i < end) {
            if (Character.isLetter(a[i])) {
                int j = i;
                while (j < end && Character.isLetter(a[j])) {
                    j++;
                }
                if (inside) {
                    if (j == a.length) {
                        char crash = a[j];
                    }
                    counts[1]++;
                } else {
                    counts[0] = Math.max(counts[0], j - i);
                }
                i = j;
            } else {
                i++;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(args.length == 0 ? System.in : new FileInputStream(args[0])));
                PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {
            in.readLine();
            new ProblemB().solve(in.readLine().toCharArray(), out);
        }
    }
}

