            flg = false;
            flushWord();
        } else if (flg) {
            if (ch != '_') {
                word.append(ch);
            } else {
                flushWord();
            }
        } else if (ch != '_') {
            cont++;
            if (index == total - 1 && cont >= mayor) {
                mayor = cont;
            }
        } else {
            resetOutsideLength();
        }
    }

    private static void resetOutsideLength() {
        if (cont >= mayor) {
            mayor = cont;
        }
        cont = 0;
    }

    private static void flushWord() {
        if (word.length() != 0) {
            arr.add(word.toString());
            word.setLength(0);
        }
    }
