public class forces {
    enum Zone { OUT, IN }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String z = sc.next();
        Zone zone = Zone.OUT;
        int count = 0;
        int outsideMax = 0;
        int insideWords = 0;
        for (int i = 0; i < n; i++) {
            char c = z.charAt(i);
            if (c == '_') {
                if (zone == Zone.OUT) {
                    if (count > outsideMax) outsideMax = count;
                } else {
                    if (count > 0) insideWords++;
                }
                count = 0;
            } else if (c == '(') {
                zone = Zone.IN;
                if (count > outsideMax) outsideMax = count;
                count = 0;
            } else if (c == ')') {
                zone = Zone.OUT;
                if (count > 0) insideWords++;
                count = 0;
            } else {
                count++;
            }
        }
        if (zone == Zone.OUT && count > outsideMax) outsideMax = count;
        System.out.println(outsideMax + " " + insideWords);
        sc.close();
    }
}

