public class forces {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.resetSyntax();
        st.whitespaceChars(0, 32);
        st.wordChars(33, 126);
        st.nextToken();
        int n = Integer.parseInt(st.sval);
        st.nextToken();
        String z = st.sval;
        boolean inside = false;
        int count = 0;
        int outsideMax = 0;
        int insideWords = 0;
        int i = 0;
        while (i < n) {
            char c = z.charAt(i);
            i++;
            if (c == '_') {
                if (!inside) {
                    if (count > outsideMax) outsideMax = count;
                } else {
                    if (count > 0) insideWords++;
                }
                count = 0;
            } else if (c == '(') {
                inside = true;
                if (count > outsideMax) outsideMax = count;
                count = 0;
            } else if (c == ')') {
                inside = false;
                if (count > 0) insideWords++;
                count = 0;
            } else {
                count++;
            }
        }
        if (!inside && count > outsideMax) outsideMax = count;
        System.out.println(outsideMax + " " + insideWords);
    }
}

