public class B {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        scan.nextLine();
        String s = scan.nextLine();

        int[] state = new int[4];
        // state[0]: longest outside word
        // state[1]: inside word count
        // state[2]: current outside word
        // state[3]: bit0 = inside parentheses; bit1 = current inside word present

        IntStream.range(0, n).forEachOrdered(index -> {
            char c = s.charAt(index);
            if (c == '(') {
                if (state[2] > state[0]) state[0] = state[2];
                state[2] = 0;
                state[3] |= 1;
            } else if (c == ')') {
                state[3] &= ~1;
                if ((state[3] & 2) != 0) {
                    state[1]++;
                }
                state[3] &= ~2;
            } else if (c == '_') {
                if (state[2] > state[0]) state[0] = state[2];
                state[2] = 0;
                if ((state[3] & 2) != 0) {
                    state[1]++;
                }
                state[3] &= ~2;
            } else {
                if ((state[3] & 1) != 0) {
                    state[3] |= 2;
                } else {
                    state[2]++;
                }
            }
        });

        if (state[2] > state[0]) state[0] = state[2];
        System.out.println(state[0] + " " + state[1]);
    }
}

