        int n = sc.nextInt();
        String inp = sc.next();

        int maxl = -1;
        int cur = 0;

        for (int i = 0; i < n; i++) {
            char c = inp.charAt(i);
            if (c == '_') {
                if (cur > maxl) maxl = cur;
                cur = 0;
            } else if (c != '(' && c != ')') {
                cur++;
            } else {
                if (cur > maxl) maxl = cur;
                cur = 0;
                i = closingIndex(inp, i + 1);
            }
        }

        if (cur > maxl) maxl = cur;

        int words = 0;
        for (int i = 0; i < n; i++) {
            while (i < n && inp.charAt(i) != '(') {
                i++;
            }
            if (i == n) {
                break;
            }
            int close = closingIndex(inp, i + 1);
            words += wordsInSegment(inp, i + 1, close);
            i = close;
        }

        System.out.println(maxl + " " + words);
    }

    private static int closingIndex(String s, int from) {
        while (s.charAt(from) != ')') {
            from++;
        }
        return from;
    }

    private static int wordsInSegment(String s, int start, int end) {
        int words = 0;
        int cur = 0;
        for (int j = start; j < end; j++) {
            if (s.charAt(j) == '_') {
                if (cur > 0) {
                    words++;
                }
                cur = 0;
            } else {
                cur++;
            }
        }
        if (cur > 0) {
            words++;
        }
        return words;
    }
}

