import java.io.*;
import java.util.*;

public class Main {
    long mod = 1_000_000_007;
    long[] fact;
    long[] invFact;

    long inv(long n) {
        long k = mod - 2;
        long res = 1;
        long a = n;
        while(k > 0) {
            if ((k & 1) > 0) res = (res * a) % mod;
            a = (a * a) % mod;
            k >>= 1;
        }
        return res;
    }

    long comb(int n, int r) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % mod * invFact[n - r] % mod;
    }

    class Node {
        int c50, c100, b, n;
        long am;
        ArrayList<Node> s;
        Node(int x, int y, int z) {
            c50 = x;
            c100 = y;
            b = z;
            s = new ArrayList<>();
            n = 0;
            am = 0;
        }
    }

    public void solve() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int c50 = 0, c100 = 0;
        for (int i = 0; i < n; i++) {
            if (sc.nextInt() == 100) c100++;
            else c50++;
        }

        fact = new long[51];
        invFact = new long[51];
        fact[0] = 1;
        for (int i = 1; i < 51; i++) fact[i] = fact[i - 1] * i % mod;
        for (int i = 0; i < 51; i++) invFact[i] = inv(fact[i]);

        Node[][][] ns = new Node[c50 + 1][c100 + 1][2];
        for (int i = 0; i <= c50; i++) {
            for (int j = 0; j <= c100; j++) {
                ns[i][j][0] = new Node(i, j, 0);
                ns[i][j][1] = new Node(i, j, 1);
            }
        }

        for (int i = 0; i <= c50; i++) {
            for (int j = 0; j <= c100; j++) {
                int p50c = Math.min(k / 50, i);
                int p100c = Math.min(k / 100, j);
                for (int x = p100c; x >= 0; x--) {
                    for (int y = Math.min(p50c, (k - 100 * x) / 50); y >= 0; y--) {
                        if (x == 0 && y == 0) continue;
                        ns[i][j][0].s.add(ns[i - y][j - x][1]);
                        ns[i - y][j - x][1].s.add(ns[i][j][0]);
                    }
                }
            }
        }

        ArrayList<Node> level = new ArrayList<>();
        ns[c50][c100][0].n = 1;
        ns[c50][c100][0].am = 1;
        level.add(ns[c50][c100][0]);

        while (!level.isEmpty()) {
            ArrayList<Node> next = new ArrayList<>();
            for (Node cur : level) {
                for (Node ch : cur.s) {
                    if (ch.n == 0 || ch.n == cur.n + 1) {
                        long p1 = comb(cur.b == 0 ? cur.c50 : c50 - cur.c50, Math.abs(cur.c50 - ch.c50));
                        long p2 = comb(cur.b == 0 ? cur.c100 : c100 - cur.c100, Math.abs(cur.c100 - ch.c100));
                        ch.am = (ch.am + (cur.am * ((p1 * p2) % mod)) % mod) % mod;
                        if (ch.n == 0) {
                            ch.n = cur.n + 1;
                            next.add(ch);
                        }
                    }
                }
            }
            level = next;
        }

        PrintWriter pw = new PrintWriter(System.out);
        pw.println((ns[0][0][1].n - 1) + "\n" + ns[0][0][1].am);
        pw.flush();
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;


public class Abood2D {

	static int N, fifty, hundred, K;
	static int memo[][][];
	static int memo2[][][][];
	static final int MOD = (int) 1e9 + 7;
	static long[][] comb; 

	static int solve(int t, int f, int h) {
		if(f == 0 && h == 0)
			return 0;

		if(memo[t][f][h] != -1)
			return memo[t][f][h];

		if(t == 1)
			return 1 + (f < fifty ? solve(0, f + 1, h) : solve(0, f, h + 1));

		int ans = (int) 1e6;

		for (int i = 0; i <= f; i++) {
			if(i * 50 > K)
				break;

			int j = Math.min(( K - i * 50) / 100, h);

			int totalW = i * 50 + j * 100;

			if(fifty - f + i > 0 && totalW > 50 || hundred - h + j > 1 && totalW > 100 || i == fifty && j == hundred)
				ans = Math.min(ans, solve(1, f - i, h - j));

		}

		return memo[t][f][h] = ans + 1;
	}

	static int solve2(int t, int f, int h, int r) {
		if(r == 0 && f == 0 && h == 0)
			return 1;


		if(r == 0)
			return 0;

		if(memo2[t][f][h][r] != -1)
			return memo2[t][f][h][r];


		int ans = 0;

		if(t == 1) {
			for (int i = 0; i <= fifty - f; ++i) {
				if(i * 50 > K)
					break;
				for (int j = 0; j <= hundred - h; ++j) {		
					if(i == 0 && j == 0)
						continue;
					int totalW = i * 50 + j * 100;

					if(totalW > K)
						break;

					ans = (int) ((1l * ans + (1l * (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD) * solve2(0, f + i, h + j, r - 1) % MOD) % MOD);

				}


			}
		} else {
			for (int i = 0; i <= f; ++i) {
				if(i * 50 > K)
					break;
				for (int j = 0; j <= h; ++j) {		
					if(i == 0 && j == 0)
						continue;
					int totalW = i * 50 + j * 100;

					if(totalW > K)
						break;

					ans = (int) ((1l * ans + (1l * (nCk(f, i) * nCk(h, j)) % MOD) * solve2(1, f - i, h - j, r - 1) % MOD)) % MOD;

				}


			}
		}

		return memo2[t][f][h][r] = ans;
	}


	static long nCk(int n, int k)		// O(n * k)
	{
		if(n < k)					
			return 0;
		if(k == 0 || k == n)		//may add k == 1 as a base case for fast calculations
			return 1;
		if(comb[n][k] != -1)
			return comb[n][k];
		if(n - k < k)				
			return comb[n][k] = nCk(n, n - k);		//reduce k to n - k
		return comb[n][k] = (((1l * n * nCk(n - 1, k - 1)) % MOD) * pow(k, MOD - 2)) % MOD;
	}

	static int pow(int x, long p) {
		if(p == 0)
			return 1;

		int ans = 1;
		if(p % 2 == 1)
			ans *= x;

		int c = pow(x, p / 2);

		ans = (int) ((1l * ((1l * ans * c) % MOD) * c) % MOD);

		return ans;
	}

	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		PrintWriter out = new PrintWriter(System.out);
		N = sc.nextInt();
		K = sc.nextInt();

		for (int i = 0; i < N; i++)
			if(sc.nextInt() == 50) fifty++; else hundred++;


		memo = new int[2][fifty + 1][hundred + 1];

		for (int i = 0; i < 2; i++)
			for (int j = 0; j <= fifty; j++)
				Arrays.fill(memo[i][j], -1);

		comb = new long[100 + 1][100 + 1];

		for (int i = 0; i <= 100; i++)
			Arrays.fill(comb[i], -1);


		int min = solve(0, fifty, hundred);

		if(min >= (int) 1e6){
			out.println(-1);
			out.println(0);
		}else {
			memo2 = new int[2][fifty + 1][hundred + 1][min + 1];

			for (int i = 0; i < 2; i++)
				for (int j = 0; j <= fifty; j++)
					for (int j2 = 0; j2 <= hundred; j2++)
						Arrays.fill(memo2[i][j][j2], -1);

			out.println(min);
			out.println(solve2(0, fifty, hundred, min));
		}


		out.flush();

	}



	static class Scanner 



	{
		StringTokenizer st;
		BufferedReader br;

		public Scanner(InputStream s){	br = new BufferedReader(new InputStreamReader(s));}

		public String next() throws IOException 
		{
			while (st == null || !st.hasMoreTokens()) 
				st = new StringTokenizer(br.readLine());
			return st.nextToken();
		}

		public int nextInt() throws IOException {return Integer.parseInt(next());}

		public long nextLong() throws IOException {return Long.parseLong(next());}

		public String nextLine() throws IOException {return br.readLine();}


		public double nextDouble() throws IOException
		{
			String x = next();
			StringBuilder sb = new StringBuilder("0");
			double res = 0, f = 1;
			boolean dec = false, neg = false;
			int start = 0;
			if(x.charAt(0) == '-')
			{
				neg = true;
				start++;
			}
			for(int i = start; i < x.length(); i++)
				if(x.charAt(i) == '.')
				{
					res = Long.parseLong(sb.toString());
					sb = new StringBuilder("0");
					dec = true;
				}
				else
				{
					sb.append(x.charAt(i));
					if(dec)
						f *= 10;
				}
			res += Long.parseLong(sb.toString()) / f;
			return res * (neg?-1:1);
		}

		public boolean ready() throws IOException {return br.ready();}



	}


