            for (int i = start; i < x.length(); i++)
                if (x.charAt(i) == '.') {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                } else {
                    sb.append(x.charAt(i));
                    if (dec)
                        f *= 10;
                }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg ? -1 : 1);
        }

        public boolean ready() throws IOException { return br.ready(); }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Abood2D {

    static int N, fifty, hundred, K;
    static int memo[][][];
    static final int MOD = (int) 1e9 + 7;
    static long[][] comb;

    static int solve(int t, int f, int h) {
        if (f == 0 && h == 0)
            return 0;

        if (memo[t][f][h] != -1)
            return memo[t][f][h];

        if (t == 1)
            return 1 + (f < fifty ? solve(0, f + 1, h) : solve(0, f, h + 1));

        int ans = (int) 1e6;

        for (int i = 0; i <= f; i++) {
            if (i * 50 > K)
                break;
            int j = Math.min((K - i * 50) / 100, h);
            int totalW = i * 50 + j * 100;
            if ((fifty - f + i > 0 && totalW > 50) || (hundred - h + j > 1 && totalW > 100) || (i == fifty && j == hundred))
                ans = Math.min(ans, solve(1, f - i, h - j));
        }

        return memo[t][f][h] = ans + 1;
    }

    static int countWays(int min) {
        int[][][][] dp = new int[2][fifty + 1][hundred + 1][min + 1];
        for (int t = 0; t < 2; t++)
            dp[t][0][0][0] = 1;

        for (int r = 1; r <= min; r++) {
            for (int t = 0; t <= 1; t++) {
                for (int f = 0; f <= fifty; f++) {
                    for (int h = 0; h <= hundred; h++) {
                        long ans = 0;

                        if (t == 1) {
                            for (int i = 0; i <= fifty - f; ++i) {
                                if (i * 50 > K)
                                    break;
                                for (int j = 0; j <= hundred - h; ++j) {
                                    if (i == 0 && j == 0)
                                        continue;
                                    int totalW = i * 50 + j * 100;
                                    if (totalW > K)
                                        break;
                                    long ways = (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD;
                                    ans = (ans + ways * dp[0][f + i][h + j][r - 1]) % MOD;
                                }
                            }
                        } else {
                            for (int i = 0; i <= f; ++i) {
                                if (i * 50 > K)
                                    break;
                                for (int j = 0; j <= h; ++j) {
                                    if (i == 0 && j == 0)
                                        continue;
                                    int totalW = i * 50 + j * 100;
                                    if (totalW > K)
                                        break;
                                    long ways = (nCk(f, i) * nCk(h, j)) % MOD;
                                    ans = (ans + ways * dp[1][f - i][h - j][r - 1]) % MOD;
                                }
                            }
                        }

                        dp[t][f][h][r] = (int) ans;
                    }
                }
            }
        }

        return dp[0][fifty][hundred][min];
    }

    static long nCk(int n, int k) {
        if (n < k)
            return 0;
        if (k == 0 || k == n)
            return 1;
        if (comb[n][k] != -1)
            return comb[n][k];
        if (n - k < k)
            return comb[n][k] = nCk(n, n - k);
        return comb[n][k] = (((1L * n * nCk(n - 1, k - 1)) % MOD) * pow(k, MOD - 2)) % MOD;
    }

    static int pow(int x, long p) {
        if (p == 0)
            return 1;
        int ans = 1;
        if (p % 2 == 1)
            ans *= x;
        int c = pow(x, p / 2);
        ans = (int) ((1L * ((1L * ans * c) % MOD) * c) % MOD);
        return ans;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        N = sc.nextInt();
        K = sc.nextInt();

        for (int i = 0; i < N; i++)
            if (sc.nextInt() == 50) fifty++; else hundred++;

        memo = new int[2][fifty + 1][hundred + 1];
        for (int i = 0; i < 2; i++)
            for (int j = 0; j <= fifty; j++)
                Arrays.fill(memo[i][j], -1);

        comb = new long[100 + 1][100 + 1];
        for (int i = 0; i <= 100; i++)
            Arrays.fill(comb[i], -1);

        int min = solve(0, fifty, hundred);

        if (min >= (int) 1e6) {
            out.println(-1);
            out.println(0);
        } else {
            out.println(min);
            out.println(countWays(min));
        }

        out.flush();
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) { br = new BufferedReader(new InputStreamReader(s)); }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException { return Integer.parseInt(next()); }
        public long nextLong() throws IOException { return Long.parseLong(next()); }
        public String nextLine() throws IOException { return br.readLine(); }

        public double nextDouble() throws IOException {
            String x = next();
            StringBuilder sb = new StringBuilder("0");
            double res = 0, f = 1;
            boolean dec = false, neg = false;
            int start = 0;
            if (x.charAt(0) == '-') {
                neg = true;
                start++;
            }
            for (int i = start; i < x.length(); i++)
                if (x.charAt(i) == '.') {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                } else {
                    sb.append(x.charAt(i));
                    if (dec)
                        f *= 10;
                }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg ? -1 : 1);
        }

        public boolean ready() throws IOException { return br.ready(); }
    }
}

import java.io.OutputStream;
