            q.add(0);
            while (!q.isEmpty()) {
                int idx = q.poll();
                int x = (idx / 2) / 200;
                int y = (idx / 2) % 200;
                int z = idx & 1;
                long d = dist[idx];
                int limX = (z == 0) ? cnt1 - x : x;
