        }

        void relax(Queue<State> queue, long[][][] dist, long[][][] dp,
                   int nx, int ny, int nz, long nd, long ways) {
            if (dist[nx][ny][nz] >= nd) {
                if (dist[nx][ny][nz] > nd) {
