public class Main {
    static final int MOD = 1000000007;
    static int cap, totalF, totalS;
    static long[][] C;
    static List<int[]>[][] moves;

    static int encode(int f, int s, int b) {
        return ((f * (totalS + 1) + s) << 1) | b;
    }

    static int decodeF(int code) {
        return (code >> 1) / (totalS + 1);
    }

    static int decodeS(int code) {
        return (code >> 1) % (totalS + 1);
    }

    static int decodeB(int code) {
        return code & 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        cap = sc.nextInt() / 50;
        totalF = 0;
        totalS = 0;
        for (int i = 0; i < n; i++) {
            if (sc.nextInt() == 100) totalF++;
            else totalS++;
        }

        C = new long[51][51];
        for (int i = 0; i <= 50; i++) {
            C[i][0] = C[i][i] = 1;
            for (int j = 1; j < i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }

        moves = new List[totalF + 1][totalS + 1];
        for (int a = 0; a <= totalF; a++) {
            for (int b = 0; b <= totalS; b++) {
                List<int[]> list = new ArrayList<>();
                for (int i = 0; i <= a; i++) {
                    for (int j = 0; j <= b; j++) {
                        if (i + j > 0 && 2 * i + j <= cap) {
                            list.add(new int[]{i, j});
                        }
                    }
                }
                moves[a][b] = list;
            }
        }

        Map<Integer, Long> cur = new HashMap<>();
        cur.put(encode(totalF, totalS, 1), 1L);
        int target = encode(0, 0, 0);

        for (int rides = 1; rides <= 200; rides++) {
            Map<Integer, Long> next = new HashMap<>();
            for (Map.Entry<Integer, Long> e : cur.entrySet()) {
                int code = e.getKey();
                long w = e.getValue();
                int f = decodeF(code);
                int s = decodeS(code);
                int b = decodeB(code);

                if (b == 1) {
                    for (int[] mv : moves[f][s]) {
                        int i = mv[0];
                        int j = mv[1];
                        long add = w * C[f][i] % MOD * C[s][j] % MOD;
                        int nc = encode(f - i, s - j, 0);
                        Long old = next.get(nc);
                        long nv = add + (old == null ? 0 : old);
                        if (nv >= MOD) nv -= MOD;
                        if (nv == 0) next.remove(nc);
                        else next.put(nc, nv);
                    }
                } else {
                    for (int[] mv : moves[totalF - f][totalS - s]) {
                        int i = mv[0];
                        int j = mv[1];
                        long add = w * C[totalF - f][i] % MOD * C[totalS - s][j] % MOD;
                        int nc = encode(f + i, s + j, 1);
                        Long old = next.get(nc);
                        long nv = add + (old == null ? 0 : old);
                        if (nv >= MOD) nv -= MOD;
                        if (nv == 0) next.remove(nc);
                        else next.put(nc, nv);
                    }
                }
            }

            Long ways = next.get(target);
            if (ways != null && ways != 0) {
                System.out.println(rides);
                System.out.println(ways);
                return;
            }
            cur = next;
            if (cur.isEmpty()) break;
        }

        System.out.println(-1);
        System.out.println(0);
    }
}

