import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Deque<Character> stack = new ArrayDeque<>();
        int count = 0;
        for (char c : sc.next().toCharArray()) {
            if (stack.isEmpty() || stack.peek().charValue() == c) {
                stack.push(c);
            } else {
                if ((stack.size() & 1) == 0) {
                    count++;
                }
                stack.clear();
                stack.push(c);
            }
        }
        if ((stack.size() & 1) == 0) {
            count++;
        }
        System.out.print(count);
    }
}

