import java.util.Scanner;

public class Main {
    private static boolean isEven(int number) {
        return number % 2 == 0;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        char[] dna = sc.next().toCharArray();
        int answer = 0;
        int counter = 1;
        char previous = dna[0];

        for (int i = 1; i < dna.length; i++) {
            char current = dna[i];
            if (previous != current) {
                previous = current;
                continue;
            }
            counter++;
            if (i == dna.length - 1) {
                if (isEven(counter)) {
                    answer++;
                    counter = 1;
                }
            } else if (dna[i + 1] != previous && isEven(counter)) {
                answer++;
                counter = 1;
            }
        }

        System.out.println(answer);
    }
}

