    private static int countEvenRuns(String s, int i, int runLen, int toPrint) {
        if (i >= s.length()) {
            return toPrint;
        }
        if (i + 1 < s.length() && s.charAt(i) == s.charAt(i + 1)) {
            return countEvenRuns(s, i + 1, runLen + 1, toPrint);
