public class Main {
    static class RunCounter {
        int previous;
        int runLength;
        int answer;
        boolean started;

        void add(int c) {
            if (!started) {
                previous = c;
                runLength = 1;
                started = true;
            } else if (c == previous) {
                runLength++;
            } else {
                if ((runLength & 1) == 0)
                    answer++;
                previous = c;
                runLength = 1;
            }
        }

        int result() {
            if (started && (runLength & 1) == 0)
                answer++;
            return answer;
        }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        String s = in.next();
        RunCounter counter = s.chars().collect(RunCounter::new, RunCounter::add, (a, b) -> {});
        out.printLine(counter.result());
        out.close();
    }
}

