import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner pm = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        String s = pm.next();
        AtomicInteger ans = new AtomicInteger(0);
        AtomicInteger prev = new AtomicInteger(s.charAt(0));
        AtomicInteger count = new AtomicInteger(1);
        IntStream.range(1, s.length()).forEachOrdered(i -> {
            int c = s.charAt(i);
            if (c == prev.get()) {
                count.incrementAndGet();
            } else {
                if ((count.get() & 1) == 0) {
                    ans.incrementAndGet();
                }
                prev.set(c);
                count.set(1);
            }
        });
        if ((count.get() & 1) == 0) {
            ans.incrementAndGet();
        }
        System.out.println(ans.get());
    }
}

