    public static long countSubarraysSumToK(long[] arr, long sum) {
        HashMap<Long, Long> map = new HashMap<>();
        int n = arr.length;
        long prefixsum = 0;
        long count = 0L;
        for (int i = 0; i < n; i++) {
            prefixsum += arr[i];
            if (sum == prefixsum) count++;
            if (map.containsKey(prefixsum - sum)) count += map.get(prefixsum - sum);
            map.put(prefixsum, map.getOrDefault(prefixsum, 0L) + 1);
        }
        return count;
    }

    public static ArrayList<Integer> kmpAlgorithm(String str, String pat) {
        ArrayList<Integer> list = new ArrayList<>();
        int n = str.length();
        int m = pat.length();
        String q = pat + "#" + str;
        int[] lps = new int[n + m + 1];
        longestPefixSuffix(lps, q, n + m + 1);
        for (int i = m + 1; i < n + m + 1; i++) {
            if (lps[i] == m) list.add(i - 2 * m);
        }
        return list;
    }

    public static void longestPefixSuffix(int[] lps, String str, int n) {
        lps[0] = 0;
        for (int i = 1; i <= n - 1; i++) {
            int l = lps[i - 1];
            while (l > 0 && str.charAt(i) != str.charAt(l)) l = lps[l - 1];
            if (str.charAt(i) == str.charAt(l)) l++;
            lps[i] = l;
        }
    }

    public static void eulerTotientFunction(int[] arr, int n) {
        for (int i = 1; i <= n; i++) arr[i] = i;
        for (int i = 2; i <= n; i++) {
            if (arr[i] == i) {
                arr[i] = i - 1;
