            } while (c <= ' ' && c != -1);
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = System.in.read();
            }
            while (c > ' ') {
                x = x * 10 + (c - '0');
                c = System.in.read();
            }
            return neg ? -x : x;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
