public class E {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    static FastReader s = new FastReader();
    static PrintWriter out = new PrintWriter(System.out);

    private static int[] rai(int n) {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextInt();
        }
        return arr;
    }

    private static int[][] rai(int n, int m) {
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = s.nextInt();
            }
        }
        return arr;
    }

    private static long[] ral(int n) {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = s.nextLong();
        }
        return arr;
    }

    private static long[][] ral(int n, int m) {
        long[][] arr = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = s.nextLong();
            }
        }
        return arr;
    }

    private static int ri() {
        return s.nextInt();
    }

    private static long rl() {
        return s.nextLong();
    }

    private static String rs() {
        return s.next();
    }

    static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    static int bsearch(List<Long> list,long val,int ind)
    {
        int l=ind,r=list.size()-1;
        int res=list.size();

        while(l<=r)
        {
            int mid=(l+r)/2;
            if(list.get(mid)>val)
            {
                if(mid==0)
                {
                    return mid;
                }
                if(list.get(mid-1)<=val)
                {
                    return mid;
                }
                r=mid-1;
            }
            else
            {
                l=mid+1;
            }
        }
        return res;

    }

    static long calc(List<Node> list,long[] b,int i)
    {
        if(i==3)
        {
            return 0;
        }


        //bInd
        Node first = list.get(i);
        int bInd = (first.ind - 1);
        if(bInd==-1)
        {
            bInd=2;
        }


        long min1 = Math.min(first.val, b[bInd]);
        first.val -= min1;
        b[bInd] -= min1;


        long min2 = Math.min(first.val, b[first.ind]);
        first.val -= min2;
        b[first.ind] -= min2;
        long sum = first.val;
        sum+=calc(list,b,i+1);
        first.val+=min1+min2;
        b[bInd]+=min1;
        b[first.ind]+=min2;



        //first.ind

        first = list.get(i);
        bInd = (first.ind - 1);
        if(bInd==-1)
        {
            bInd=2;
        }

        min1 = Math.min(first.val, b[first.ind]);
        first.val -= min1;
        b[first.ind] -= min1;


        min2 = Math.min(first.val, b[bInd]);
        first.val -= min2;
        b[bInd] -= min2;
        long sum2 = first.val;
        sum2+=calc(list,b,i+1);
        first.val+=min1+min2;
        b[bInd]+=min2;
        b[first.ind]+=min1;

        return Math.min(sum,sum2);
    }
    public static void main(String[] args) {
        StringBuilder ans = new StringBuilder();
//        int t = ri();
        int t = 1;
        while (t-- > 0) {
            int n=ri();
            long[] a=ral(3);
            long[] b=ral(3);

            long max=Math.min(a[0],b[1])+Math.min(a[1],b[2])+Math.min(a[2],b[0]);
            long min=Math.max(0,a[0]+b[1]-n)+Math.max(0,a[1]+b[2]-n)+Math.max(0,a[2]+b[0]-n);
