public class Main {
    static int minAns = Integer.MAX_VALUE;
    static int[] aOrig;
    static int[] bOrig;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int a1 = in.nextInt();
        int a2 = in.nextInt();
        int a3 = in.nextInt();
        int b1 = in.nextInt();
        int b2 = in.nextInt();
        int b3 = in.nextInt();

        aOrig = new int[]{a1, a2, a3};
        bOrig = new int[]{b1, b2, b3};

        int max = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);

        int[] order = new int[3];
        boolean[] used = new boolean[3];
        permute(0, order, used);

        System.out.println(minAns + " " + max);
    }

    static void permute(int pos, int[] order, boolean[] used) {
        if (pos == 3) {
            int[] a = aOrig.clone();
            int[] b = bOrig.clone();
            for (int idx : order) {
                battle(a, b, idx);
            }
            int sum = a[0] + a[1] + a[2];
            if (sum < minAns) {
                minAns = sum;
            }
            return;
        }
        for (int i = 0; i < 3; i++) {
            if (!used[i]) {
                used[i] = true;
                order[pos] = i;
                permute(pos + 1, order, used);
                used[i] = false;
            }
        }
    }

    static void battle(int[] a, int[] b, int i) {
        int first = (i + 1) % 3;
        int second = i;
        if (b[i] > a[first]) {
            b[i] -= a[first];
            a[first] = 0;
            if (b[i] > a[second]) {
                b[i] -= a[second];
                a[second] = 0;
            } else {
                a[second] -= b[i];
                b[i] = 0;
            }
        } else {
            a[first] -= b[i];
            b[i] = 0;
        }
    }
}

