    LongLongMap cache = new LongLongMap();
    char[] cs;

    class LongLongMap {
        long[] keys = new long[1 << 16];
        long[] values = new long[1 << 16];
        boolean[] used = new boolean[1 << 16];
        int size = 0;
        int mask = keys.length - 1;

        Long get(long key) {
            int idx = hash(key);
            while (used[idx]) {
                if (keys[idx] == key) return values[idx];
                idx = (idx + 1) & mask;
            }
            return null;
        }

        void put(long key, long val) {
            if ((size + 1) * 2 >= keys.length) resize();
            int idx = hash(key);
            while (used[idx]) {
                if (keys[idx] == key) {
                    values[idx] = val;
                    return;
                }
                idx = (idx + 1) & mask;
            }
            used[idx] = true;
            keys[idx] = key;
            values[idx] = val;
            size++;
        }

        void resize() {
            long[] oldKeys = keys;
            long[] oldValues = values;
            boolean[] oldUsed = used;
            int oldLength = keys.length;
            keys = new long[oldLength << 1];
            values = new long[oldLength << 1];
            used = new boolean[oldLength << 1];
            mask = keys.length - 1;
            size = 0;
            for (int i = 0; i < oldLength; i++) {
                if (oldUsed[i]) put(oldKeys[i], oldValues[i]);
            }
        }

