    long best = Long.MAX_VALUE;
    String str;
    Map<Long, Long> cache = new HashMap<>();
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    static class Frame {
        long x, y;
        int v1, v2;
        Frame(long x, long y, int v1, int v2) { this.x = x; this.y = y; this.v1 = v1; this.v2 = v2; }
    }

    public static void main(String[] args) {
        Test te = new Test();
        te.start();
        writer.flush();
    }

    int readInt() {
        int ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            int c;
            while ((c = br.read()) != -1) {
                if (c == '-') {
                    start = true;
                    neg = true;
                    continue;
                } else if (c >= '0' && c <= '9') {
                    start = true;
                    ans = ans * 10 + c - '0';
                } else if (start) break;
            }
        } catch (IOException e) {}
        return neg ? -ans : ans;
    }

    long readLong() {
        long ans = 0;
        boolean neg = false;
        try {
            boolean start = false;
            int c;
            while ((c = br.read()) != -1) {
                if (c == '-') {
                    start = true;
                    neg = true;
                    continue;
                } else if (c >= '0' && c <= '9') {
                    start = true;
                    ans = ans * 10 + c - '0';
                } else if (start) break;
            }
        } catch (IOException e) {}
        return neg ? -ans : ans;
    }

    String readString() {
        StringBuilder b = new StringBuilder();
        try {
            boolean start = false;
            int c;
            while ((c = br.read()) != -1) {
                if (!Character.isWhitespace(c)) {
                    start = true;
                    b.append((char) c);
                } else if (start) break;
            }
        } catch (IOException e) {}
        return b.toString();
    }

    void computeBinomial(int maxN) {
        rows = new ArrayList<>();
        for (int i = 0; i <= maxN; i++) {
            long[] row = new long[i + 1];
            row[0] = row[i] = 1;
            for (int j = 1; j < i; j++) {
                row[j] = rows.get(i - 1)[j - 1] + rows.get(i - 1)[j];
            }
            rows.add(row);
        }
    }

    void dfs(long x, long y, int v1, int v2) {
        Stack<Frame> stack = new Stack<>();
        stack.push(new Frame(x, y, v1, v2));
        while (!stack.isEmpty()) {
            Frame f = stack.pop();
            long diff = Math.abs(f.x - f.y);
            if (best <= 1 || diff - rows.get(f.v1)[R] * rows.get(f.v2)[R] >= best) continue;
            if (f.v1 == R - 1 && f.v2 == R - 1) {
                if (diff < best) best = diff;
                continue;
            }
            if (f.v2 >= R) {
                long cur = rows.get(f.v2)[R] - rows.get(f.v2 - 1)[R];
                long other = rows.get(f.v1)[R];
                stack.push(new Frame(f.x + cur * other, f.y, f.v1, f.v2 - 1));
            }
            if (f.v1 >= R) {
                long cur = rows.get(f.v1)[R] - rows.get(f.v1 - 1)[R];
                long other = rows.get(f.v2)[R];
                stack.push(new Frame(f.x, f.y + cur * other, f.v1 - 1, f.v2));
            }
        }
    }

    long solve(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (diff - rows.get(v1)[R] * rows.get(v2)[R] > best) return 0;
        long key = x * 10000 + v1 * 100 + v2;
        Long v = cache.get(key);
        if (v != null) return v;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return rows.get(v1 + v2)[v1];
            }
            return 0;
        }
        long ans = 0;
        char c = str.charAt(v1 + v2 - 1);
        if (c != 'B') {
            long cur = rows.get(v1)[R] - rows.get(v1 - 1)[R];
            long other = rows.get(v2)[R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        if (c != 'A') {
            long cur = rows.get(v2)[R] - rows.get(v2 - 1)[R];
            long other = rows.get(v1)[R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        cache.put(key, ans);
        return ans;
    }

    void start() {
        R = readInt();
        C = readInt();
        int maxN = 2 * (R + C);
        computeBinomial(maxN);
        long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R)
            if (x > y) {
                long cur = rows.get(v1)[R] - rows.get(v1 - 1)[R];
                long other = rows.get(v2)[R];
                y += cur * other;
                v1--;
            } else {
                long cur = rows.get(v2)[R] - rows.get(v2 - 1)[R];
                long other = rows.get(v1)[R];
                x += cur * other;
                v2--;
            }
        best = Math.abs(x - y);
        dfs(0, 0, R + C, R + C);
        str = readString();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
        }
        long ans = solve(0, 0, R + C, R + C);
        writer.println(ans);
    }
}

import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.math.BigInteger;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Test {
    static PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    int R, C;
    BigInteger[][] ch = new BigInteger[61][61];
    int[] cntA = new int[61], cntB = new int[61];
    BigInteger best = BigInteger.valueOf(Long.MAX_VALUE);
    String str;
    Map<String, BigInteger> cache = new HashMap<>();
    Scanner sc = new Scanner(System.in);

    public static void main(String[] args) {
        Test te = new Test();
        te.start();
        writer.flush();
    }

    int readInt() { return sc.nextInt(); }
    long readLong() { return sc.nextLong(); }
    String readString() { return sc.next(); }

    void dfs(BigInteger x, BigInteger y, int v1, int v2) {
        BigInteger diff = x.subtract(y).abs();
        if (best.compareTo(BigInteger.ONE) <= 0 || diff.subtract(ch[v1][R].multiply(ch[v2][R])).compareTo(best) >= 0) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff.compareTo(best) < 0) best = diff;
            return;
        }
        if (v1 >= R) {
            BigInteger cur = ch[v1][R].subtract(ch[v1 - 1][R]);
            BigInteger other = ch[v2][R];
            dfs(x, y.add(cur.multiply(other)), v1 - 1, v2);
        }
        if (v2 >= R) {
            BigInteger cur = ch[v2][R].subtract(ch[v2 - 1][R]);
            BigInteger other = ch[v1][R];
            dfs(x.add(cur.multiply(other)), y, v1, v2 - 1);
        }
    }

    BigInteger solve(BigInteger x, BigInteger y, int v1, int v2) {
        BigInteger diff = x.subtract(y).abs();
        if (diff.subtract(ch[v1][R].multiply(ch[v2][R])).compareTo(best) > 0) return BigInteger.ZERO;
        String key = x.toString() + "," + v1 + "," + v2;
        BigInteger v = cache.get(key);
        if (v != null) return v;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return ch[v1 + v2][v1];
            }
            return BigInteger.ZERO;
        }
        BigInteger ans = BigInteger.ZERO;
        char c = str.charAt(v1 + v2 - 1);
        if (c != 'B') {
            BigInteger cur = ch[v1][R].subtract(ch[v1 - 1][R]);
            BigInteger other = ch[v2][R];
            ans = ans.add(solve(x, y.add(cur.multiply(other)), v1 - 1, v2));
        }
        if (c != 'A') {
            BigInteger cur = ch[v2][R].subtract(ch[v2 - 1][R]);
            BigInteger other = ch[v1][R];
            ans = ans.add(solve(x.add(cur.multiply(other)), y, v1, v2 - 1));
        }
        cache.put(key, ans);
        return ans;
    }

    void start() {
        R = readInt();
        C = readInt();
        int maxN = 2 * (R + C);
        for (int i = 0; i <= maxN; i++) {
            ch[i] = new BigInteger[i + 1];
            for (int j = 0; j <= i; j++) {
                if (j == 0 || j == i) ch[i][j] = BigInteger.ONE;
                else ch[i][j] = ch[i - 1][j - 1].add(ch[i - 1][j]);
            }
        }
        BigInteger x = BigInteger.ZERO, y = BigInteger.ZERO;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R) {
            if (x.compareTo(y) > 0) {
                BigInteger cur = ch[v1][R].subtract(ch[v1 - 1][R]);
                BigInteger other = ch[v2][R];
                y = y.add(cur.multiply(other));
                v1--;
            } else {
                BigInteger cur = ch[v2][R].subtract(ch[v2 - 1][R]);
                BigInteger other = ch[v1][R];
                x = x.add(cur.multiply(other));
                v2--;
            }
        }
        best = x.subtract(y).abs();
        dfs(BigInteger.ZERO, BigInteger.ZERO, R + C, R + C);
        str = readString();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
        }
        BigInteger ans = solve(BigInteger.ZERO, BigInteger.ZERO, R + C, R + C);
        writer.println(ans.longValue());
    }
}

import java.io.BufferedWriter;
import java.io.DataInputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;

public class Test {
    static PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    int R, C;
    long[][] ch;
    int[] cntA = new int[61], cntB = new int[61];
    long best = Long.MAX_VALUE;
    String str;
    Map<Integer, Map<Integer, Map<Long, Long>>> cache = new HashMap<>();

    static class FastReader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;
        public FastReader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }
        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                bytesRead = din.read(buffer, 0, BUFFER_SIZE);
                if (bytesRead == -1) return -1;
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }
        public int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }
        public long nextLong() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -ret : ret;
        }
        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            byte c = read();
            while (c <= ' ') c = read();
            do {
                sb.append((char) c);
            } while ((c = read()) > ' ');
            return sb.toString();
        }
    }

    FastReader fr = new FastReader();

    int readInt() { try { return fr.nextInt(); } catch (IOException e) { return 0; } }
    long readLong() { try { return fr.nextLong(); } catch (IOException e) { return 0; } }
    String readString() { try { return fr.next(); } catch (IOException e) { return ""; } }

    Long cacheGet(int v1, int v2, long x) {
        Map<Integer, Map<Long, Long>> m1 = cache.get(v1);
        if (m1 == null) return null;
        Map<Long, Long> m2 = m1.get(v2);
        if (m2 == null) return null;
        return m2.get(x);
    }
    void cachePut(int v1, int v2, long x, long val) {
        cache.computeIfAbsent(v1, k -> new HashMap<>())
             .computeIfAbsent(v2, k -> new HashMap<>())
             .put(x, val);
    }

    public static void main(String[] args) {
        Test te = new Test();
        te.start();
        writer.flush();
    }

    void computeBinomial(int maxN) {
        ch = new long[maxN + 1][];
        long[] prev = null;
        for (int i = 0; i <= maxN; i++) {
            long[] cur = new long[i + 1];
            cur[0] = cur[i] = 1;
            for (int j = 1; j < i; j++) {
                cur[j] = prev[j - 1] + prev[j];
            }
            ch[i] = cur;
            prev = cur;
        }
    }

    void dfs(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (best <= 1 || diff - ch[v1][R] * ch[v2][R] >= best) return;
        if (v1 == R - 1 && v2 == R - 1) {
            if (diff < best) best = diff;
            return;
        }
        if (v1 >= R) {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            dfs(x, y + cur * other, v1 - 1, v2);
        }
        if (v2 >= R) {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            dfs(x + cur * other, y, v1, v2 - 1);
        }
    }

    long solve(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (diff - ch[v1][R] * ch[v2][R] > best) return 0;
        Long v = cacheGet(v1, v2, x);
        if (v != null) return v;
        if (v1 < R || v2 < R) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                return ch[v1 + v2][v1];
            }
            return 0;
        }
        long ans = 0;
        char c = str.charAt(v1 + v2 - 1);
        if (c != 'A') {
            long cur = ch[v2][R] - ch[v2 - 1][R];
            long other = ch[v1][R];
            ans += solve(x + cur * other, y, v1, v2 - 1);
        }
        if (c != 'B') {
            long cur = ch[v1][R] - ch[v1 - 1][R];
            long other = ch[v2][R];
            ans += solve(x, y + cur * other, v1 - 1, v2);
        }
        cachePut(v1, v2, x, ans);
        return ans;
    }

    void start() {
        R = readInt();
        C = readInt();
        int maxN = 2 * (R + C);
        computeBinomial(maxN);
        long x = 0, y = 0;
        int v1 = R + C, v2 = R + C;
        while (v1 >= R && v2 >= R)
            if (x > y) {
                long cur = ch[v1][R] - ch[v1 - 1][R];
                long other = ch[v2][R];
                y += cur * other;
                v1--;
            } else {
                long cur = ch[v2][R] - ch[v2 - 1][R];
                long other = ch[v1][R];
                x += cur * other;
                v2--;
            }
        best = Math.abs(x - y);
        dfs(0, 0, R + C, R + C);
        str = readString();
        for (int i = 0; i < 2 * (R + C); i++) {
            cntA[i + 1] = cntA[i] + (str.charAt(i) == 'A' ? 1 : 0);
            cntB[i + 1] = cntB[i] + (str.charAt(i) == 'B' ? 1 : 0);
        }
        long ans = solve(0, 0, R + C, R + C);
        writer.println(ans);
    }
}

