        Deque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{x, y, v1, v2});
        while (!stack.isEmpty()) {
            long[] cur = stack.pop();
            long cx = cur[0];
            long cy = cur[1];
            int a = (int) cur[2];
