            return;
        }
        int n = 0;
        for (long v = 1; v <= 2_000_000_000L; v *= w) {
            n++;
        }
        long target = m;
        int carry = 0;
        int i = 0;
        boolean ok = true;
        while (target != 0 || carry != 0) {
            if (i >= n) {
                ok = false;
                break;
            }
            long r = target % w;
            target /= w;
            long v = r + carry;
            if (v == 0 || v == 1) {
                carry = 0;
            } else if (v == w - 1 || v == w) {
                carry = 1;
            } else {
                ok = false;
                break;
            }
            i++;
        }
        System.out.println(ok ? "YES" : "NO");
    }
}

