        while (m > 0) {
            arr[cntr++] = m % w;
            m /= w;
        }

        System.out.println(check(arr, 0, cntr, w) ? "YES" : "NO");
    }
}

import java.util.Scanner;
import java.util.Stack;

public class sd3 {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int w = s.nextInt();
        int m = s.nextInt();

        Stack<Integer> digits = new Stack<Integer>();
        int cntr = 0;
        while (m > 0) {
            if (cntr == 40) {
                throw new ArrayIndexOutOfBoundsException(cntr);
            }
            digits.push(m % w);
            m /= w;
            cntr++;
        }

        Stack<Integer> process = new Stack<Integer>();
        process.push(0);
        while (!digits.isEmpty()) {
            process.push(digits.pop());
        }

        boolean flag = true;
        while (!process.isEmpty()) {
            int d = process.pop();
            if (d != 0 && d != 1 && d != w && d != w - 1) {
                flag = false;
                break;
            }
            if (d == w || d == w - 1) {
                if (!process.isEmpty()) {
                    process.push(process.pop() + 1);
                }
            }
        }

        System.out.println(flag ? "YES" : "NO");
    }
}

import java.util.Scanner;

public class sd4 {
    static boolean check(long m, int w, int i, int stop) {
        if (i > stop) {
            return true;
        }
        if (m <= 0) {
            return true;
        }

        int d = (int) (m % w);
        m /= w;
        if (d == w || d == w - 1) {
            m++;
        }

        if (d != 0 && d != 1 && d != w && d != w - 1) {
            return false;
        }

        if (i == stop) {
            return true;
        }
        return check(m, w, i + 1, stop);
    }

    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int w = s.nextInt();
        int m = s.nextInt();

        long temp = m;
        int stop = 0;
        while (temp > 0) {
            if (stop == 40) {
                throw new ArrayIndexOutOfBoundsException(stop);
            }
            temp /= w;
            stop++;
        }

        System.out.println(check(m, w, 0, stop) ? "YES" : "NO");
    }
}

